INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-pro-99-europe', 'N64', 'NHL Pro 99 (Europe)', '1998', 'Sports', 'Electronic Arts', '2', 'Sports Simulation', 'Ice hockey simulation with arcade elements and seasonal play.', 'Win the Stanley Cup by defeating opponents in realistic hockey matches.', 'A professional hockey sim featuring real teams and fast-paced rink action.', 'Experience the intensity of professional hockey in NHL Pro 99 (Europe) for N64. Master the puck, execute precision passes, and lead your favorite NHL team to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nightmare-creatures-usa', 'N64', 'Nightmare Creatures (USA)', '1997', 'Action', 'Hudson Soft / Kalisto', '1', 'Survival Horror', 'Third-person gothic action-horror with hack-and-slash combat.', 'Stop Adam Crowley’s mutated monsters from destroying 19th-century London.', 'Dark action-horror game set in a monster-infested Victorian era.', 'Enter the nightmare in Nightmare Creatures (USA), a chilling action game for N64. Fight terrifying monsters using unique weapons and combos as you uncover a dark plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-mario-64-wip', 'N64', 'Ninja Mario 64 (WIP)', '1996', 'Platform', 'Nintendo', '1', '3D Platformer', '3D platforming and stealth mechanics based on the Mario engine.', 'Navigate through custom levels using ninja-inspired agility and skills.', 'A creative ROM hack featuring Mario with ninja-style movements.', 'Ninja Mario 64 (WIP) is a unique hack that reimagines Mario''s movement. Explore familiar and new environments with enhanced speed and acrobatic abilities in this ninja-themed project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou-64-game-gallery-japan', 'N64', 'Nintama Rantarou 64 Game Gallery (Japan)', '1999', 'Educational', 'Culture Brain', '1', 'Educational', 'Minigame collection based on the popular anime series.', 'Complete various traditional Japanese puzzles and skill-based trials.', 'A fun collection of minigames featuring the characters of Nintama Rantarou.', 'Join the young ninjas in Nintama Rantarou 64 Game Gallery (Japan). This exclusive title offers a variety of engaging minigames and puzzles perfect for fans of the classic anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-all-star!-dairantou-smash-brothers-japan', 'N64', 'Nintendo All-Star! Dairantou Smash Brothers (Japan)', '1999', 'Fighting', 'HAL Laboratory', '4', 'Platform Fighter', '2.5D crossover fighting game with a focus on knockbacks.', 'Knock opponents off the stage to be the last fighter standing.', 'The original Japanese release of the legendary Nintendo crossover fighter.', 'Nintendo All-Star! Dairantou Smash Brothers (Japan) is where the phenomenon began. Fight as Mario or Link in this iconic N64 brawler that revolutionized the fighting game genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('normal-bowser-in-final-battle', 'N64', 'Normal Bowser in final battle', '1996', 'Action', 'Nintendo', '1', 'Gameplay Modification', 'Boss rush or targeted combat encounter within Super Mario 64.', 'Defeat the final version of Bowser to rescue Princess Peach.', 'A specific gameplay mod or save state focused on the final boss fight.', 'Take on the ultimate challenge in Normal Bowser in final battle. This experience lets players jump straight into the climax of Super Mario 64 to master the final boss mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nuclear-strike-64-europe-enfr', 'N64', 'Nuclear Strike 64 (Europe) (En,Fr)', '1999', 'Action', 'Electronic Arts', '1', 'Arcade Shooter', 'Isometric vehicular combat and strategic helicopter missions.', 'Complete complex military objectives using a variety of aircraft and tanks.', 'Intense tactical helicopter combat with explosive mission-based gameplay.', 'Nuclear Strike 64 (Europe) brings strategic aerial warfare to the N64. Manage fuel and ammo while navigating dangerous warzones and completing diverse military objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nuclear-strike-64-germany', 'N64', 'Nuclear Strike 64 (Germany)', '1999', 'Action', 'Electronic Arts', '1', 'Arcade Shooter', 'Isometric vehicular combat and strategic helicopter missions.', 'Complete complex military objectives using a variety of aircraft and tanks.', 'Intense tactical helicopter combat with explosive mission-based gameplay.', 'Nuclear Strike 64 (Germany) delivers high-stakes tactical combat. Command advanced military hardware to stop a global nuclear threat in this localized European edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nuclear-strike-64-usa', 'N64', 'Nuclear Strike 64 (USA)', '1999', 'Action', 'Electronic Arts', '1', 'Arcade Shooter', 'Isometric vehicular combat and strategic helicopter missions.', 'Complete complex military objectives using a variety of aircraft and tanks.', 'Intense tactical helicopter combat with explosive mission-based gameplay.', 'Nuclear Strike 64 (USA) is the definitive North American version of this vehicular combat classic. Master the controls of various aircraft to neutralize enemy targets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nushi-zuri-64---shiokaze-ni-notte-japan', 'N64', 'Nushi Zuri 64 - Shiokaze ni Notte (Japan)', '1998', 'Simulation', 'Pack-In-Video', '1', 'Fishing Simulation', 'Realistic fishing simulation with RPG elements and travel.', 'Catch various species of fish to complete your collection and progress.', 'A deep fishing RPG that blends outdoor simulation with character growth.', 'Dive into the world of Nushi Zuri 64 - Shiokaze ni Notte (Japan). This sea-fishing adventure combines realistic angling with a charming story and beautiful Japanese coastal environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nushi-zuri-64-japan', 'N64', 'Nushi Zuri 64 (Japan)', '1998', 'Simulation', 'Pack-In-Video', '1', 'Fishing Simulation', 'Realistic fishing simulation with RPG elements and travel.', 'Catch various species of fish to complete your collection and progress.', 'A deep fishing RPG that blends outdoor simulation with character growth.', 'Explore the serene world of Nushi Zuri 64 (Japan). This fishing RPG allows players to explore beautiful landscapes while mastering the art of the catch and upgrading gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nushi-zuri-64-japan-rev-a', 'N64', 'Nushi Zuri 64 (Japan) (Rev A)', '1998', 'Simulation', 'Pack-In-Video', '1', 'Fishing Simulation', 'Realistic fishing simulation with RPG elements and travel.', 'Catch various species of fish to complete your collection and progress.', 'A deep fishing RPG that blends outdoor simulation with character growth.', 'Nushi Zuri 64 (Japan) (Rev A) provides the updated experience of the classic fishing RPG, featuring refined gameplay mechanics for a more balanced angling simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('odt-usa-enfres-proto', 'N64', 'O.D.T. (USA) (En,Fr,Es) (Proto)', '2000', 'Action', 'Infogrames', '1', 'Action Adventure', 'Third-person action-adventure with combat and exploration.', 'Explore a futuristic world and survive against hostile alien life.', 'An unreleased prototype featuring sci-fi exploration and puzzle-solving.', 'O.D.T. (USA) (Proto) is a fascinating look at an unreleased N64 title. Navigate atmospheric levels and manage resources in this ambitious sci-fi action-adventure game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ocarina-of-time---chaos-edition', 'N64', 'Ocarina of Time - Chaos Edition', '2023', 'Action', 'Nintendo', '1', 'Adventure Modification', 'Randomized or glitch-heavy 3D action-adventure.', 'Navigate a chaotic version of Hyrule where logic and assets are scrambled.', 'A modified version of Ocarina of Time where everything is unpredictable.', 'Experience Hyrule like never before in Ocarina of Time - Chaos Edition. This mod introduces random events and glitches, challenging veteran players to finish the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ocarina-of-time---gender-neutral', 'N64', 'Ocarina of Time - Gender Neutral', '2023', 'Action', 'Nintendo', '1', 'Adventure Modification', '3D action-adventure with modified character dialogue and assets.', 'Complete the classic quest of Link while using gender-neutral pronouns.', 'A thoughtful modification of the classic game for a neutral experience.', 'Ocarina of Time - Gender Neutral offers a new way to experience the legend. This mod adjusts text and references to provide a more inclusive narrative journey through Hyrule.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ocarina-of-time---gold-quest', 'N64', 'Ocarina of Time - Gold Quest', '2023', 'Action', 'Nintendo', '1', 'Adventure Modification', '3D action-adventure with a focus on gold-themed items and quests.', 'Collect all gold-related items and complete a modified story path.', 'A specialized ROM hack that changes the visual and quest focus to Gold.', 'Ocarina of Time - Gold Quest transforms the landscape of Hyrule. Search for golden treasures and complete unique challenges in this visually distinct modification of the N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ocarina-of-time---play-as-a-dragon!', 'N64', 'Ocarina of Time - Play as a Dragon!', '2023', 'Action', 'Nintendo', '1', 'Adventure Modification', '3D action-adventure featuring a dragon as the main protagonist.', 'Explore Hyrule and complete quests using the abilities of a dragon.', 'A unique character-swap mod that replaces Link with a dragon.', 'Ocarina of Time - Play as a Dragon! is a wild reimagining of the game. Fly or stomp through Hyrule, using draconic powers to defeat enemies and solve puzzles in a new way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ocarina-of-time-spaceworld-97-beta-experience', 'N64', 'Ocarina of Time Spaceworld ''97 Beta Experience', '1997', 'Action', 'Nintendo', '1', 'Development Beta', '3D action-adventure based on early development builds.', 'Explore the beta maps and mechanics as they were seen in 1997.', 'A preservation mod focused on the pre-release Spaceworld 1997 demo.', 'Ocarina of Time Spaceworld ''97 Beta Experience lets you step back in time. Explore unfinished maps and early concepts that were cut from the final release of this N64 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('off-road-challenge-europe', 'N64', 'Off Road Challenge (Europe)', '1999', 'Racing', 'Midway', '4', 'Off-Road Racing', 'Off-road racing with nitro boosts and destructive environments.', 'Finish in first place across rugged terrains and obstacle-filled tracks.', 'High-octane off-road racing with an emphasis on speed and big jumps.', 'Get ready for mud-slinging action in Off Road Challenge (Europe). Race through diverse outdoor tracks and use nitro boosts to dominate the competition in this arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('off-road-challenge-usa', 'N64', 'Off Road Challenge (USA)', '1999', 'Racing', 'Midway', '4', 'Off-Road Racing', 'Off-road racing with nitro boosts and destructive environments.', 'Finish in first place across rugged terrains and obstacle-filled tracks.', 'High-octane off-road racing with an emphasis on speed and big jumps.', 'Off Road Challenge (USA) brings the classic arcade racing experience to your N64. Upgrade your vehicle and master the off-road terrain to become the ultimate champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ogre-battle-64---person-of-lordly-caliber-japan-rev-a', 'N64', 'Ogre Battle 64 - Person of Lordly Caliber (Japan) (Rev A)', '1999', 'RPG', 'Quest / Square', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid-based movement and alignment systems.', 'Lead a revolution and make choices that determine the fate of the kingdom.', 'An epic strategy RPG with deep storytelling and complex unit management.', 'Ogre Battle 64 (Japan) (Rev A) is a sophisticated tactical RPG. Lead your army through a branching narrative where your choices determine the survival of your troops.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ogre-battle-64---person-of-lordly-caliber-usa', 'N64', 'Ogre Battle 64 - Person of Lordly Caliber (USA)', '1999', 'RPG', 'Quest / Square', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid-based movement and alignment systems.', 'Lead a revolution and make choices that determine the fate of the kingdom.', 'An epic strategy RPG with deep storytelling and complex unit management.', 'Ogre Battle 64 - Person of Lordly Caliber (USA) is a legendary title on the N64. Command vast armies and manage your reputation in this deep and engaging strategy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ogre-battle-64---person-of-lordly-caliber-usa-rev-a', 'N64', 'Ogre Battle 64 - Person of Lordly Caliber (USA) (Rev A)', '1999', 'RPG', 'Quest / Square', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid-based movement and alignment systems.', 'Lead a revolution and make choices that determine the fate of the kingdom.', 'An epic strategy RPG with deep storytelling and complex unit management.', 'Ogre Battle 64 (USA) (Rev A) offers the most polished version of the English release. Experience the massive tactical battles and intricate political story with updated game stability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-hockey-98-europe-enfrdees', 'N64', 'Olympic Hockey 98 (Europe) (En,Fr,De,Es)', '1998', 'Sports', 'Silicon Dreams Studio', '2', 'Sports Simulation', 'International ice hockey simulation with Olympic branding.', 'Win the gold medal by defeating international teams in the 1998 Games.', 'A licensed Olympic sports title featuring fast-paced hockey gameplay.', 'Relive the Nagano 1998 Winter Games in Olympic Hockey 98 (Europe). Represent your country and lead your national team to the gold in this authentic hockey sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-hockey-98-japan', 'N64', 'Olympic Hockey 98 (Japan)', '1998', 'Sports', 'Silicon Dreams Studio', '2', 'Sports Simulation', 'International ice hockey simulation with Olympic branding.', 'Win the gold medal by defeating international teams in the 1998 Games.', 'A licensed Olympic sports title featuring fast-paced hockey gameplay.', 'Olympic Hockey 98 (Japan) brings the excitement of international hockey to the N64. Compete against the world''s best teams in a quest for Olympic glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-hockey-98-usa', 'N64', 'Olympic Hockey 98 (USA)', '1998', 'Sports', 'Silicon Dreams Studio', '2', 'Sports Simulation', 'International ice hockey simulation with Olympic branding.', 'Win the gold medal by defeating international teams in the 1998 Games.', 'A licensed Olympic sports title featuring fast-paced hockey gameplay.', 'Olympic Hockey 98 (USA) features real rosters and tournament modes. Experience the speed and strategy of the Winter Olympics from the comfort of your home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onegai-monsters-japan', 'N64', 'Onegai Monsters (Japan)', '1999', 'Adventure', 'Hudson Soft', '1', 'Monster Raising', 'Monster-collecting RPG with exploration and turn-based battles.', 'Collect and train monsters to become the best trainer in the land.', 'A colorful Japanese RPG focused on monster raising and exploration.', 'Onegai Monsters (Japan) is a charming adventure where you collect and train unique creatures. Explore a vibrant world and master the strategic battle system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('only-up-64', 'N64', 'Only Up 64', '2023', 'Platform', 'Independent', '1', 'Precision Platformer', 'Vertical platformer focused on precision and physics.', 'Climb as high as possible without falling to reach the summit.', 'A challenging N64 port/mod of the viral climbing concept.', 'Test your skill in Only Up 64. Navigate a vertical obstacle course where precision is everything. One wrong move will send you back to the beginning of this intense climb.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oot-debug:-better-link-+-changeable-clothes', 'N64', 'OoT DEBUG: Better Link + Changeable Clothes', '1998', 'Action', 'Nintendo', '1', 'Debug / Development', '3D action-adventure with enhanced character models and costumes.', 'Explore Hyrule with a more detailed Link and customizable outfits.', 'A visual enhancement mod for the classic Ocarina of Time debug build.', 'OoT DEBUG: Better Link + Changeable Clothes offers a customized experience of the N64 classic. Use the debug features to swap outfits and see Link in high detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-winback-europe-enfrdeesit', 'N64', 'Operation WinBack (Europe) (En,Fr,De,Es,It)', '2001', 'Action', 'Koei', '1', 'Tactical Shooter', 'Third-person tactical shooter with cover-based mechanics.', 'Infiltrate a terrorist base and stop a weaponized satellite launch.', 'A pioneering cover-shooter with a focus on stealth and gunplay.', 'Operation WinBack (Europe) is a tactical landmark. Utilize the revolutionary cover system and engage in intense gunfights to stop a global threat in this European edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation:-christmas', 'N64', 'Operation: Christmas', '2023', 'Adventure', 'Independent', '1', 'Seasonal Event', 'Festive-themed platformer or mini-game collection.', 'Complete holiday-themed objectives to save or celebrate Christmas.', 'A cheerful seasonal mod or game centered around holiday spirit.', 'Operation: Christmas brings holiday cheer to the N64. Complete merry challenges and explore snowy landscapes in this festive-themed adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('overtime-64-wip', 'N64', 'Overtime 64 (WIP)', '2000', 'Action', 'Independent', '1', 'Prototype', '3D sports or action gameplay featuring overtime mechanics.', 'Win the match or complete the mission during extra time or sudden death.', 'A work-in-progress game or mod focused on high-pressure overtime play.', 'Overtime 64 (WIP) is an intriguing project that focuses on the most intense moments of competition. Experience the pressure of sudden death scenarios in this upcoming title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachinko-365-nichi-japan', 'N64', 'Pachinko 365 Nichi (Japan)', '1997', 'Simulation', 'ASCII Corporation', '1', 'Pachinko Simulation', 'Pachinko simulation with realistic physics and Japanese parlor mechanics.', 'Accumulate as many silver balls as possible across a full year of play.', 'A comprehensive Pachinko simulator for the Japanese N64 market.', 'Pachinko 365 Nichi (Japan) offers an authentic gambling simulation. Experience the sights and sounds of a Japanese parlor every day of the year with realistic ball physics and various machine layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacmario-v10', 'N64', 'Pacmario v1.0', '1996', 'Platform', 'Nintendo', '1', '3D Platformer', '3D platformer merging Mario world aesthetics with Pac-Man mechanics.', 'Collect all pellets in the level while avoiding classic ghosts.', 'A creative crossover mod blending Pac-Man and Super Mario 64.', 'Pacmario v1.0 is a nostalgic mashup for the N64. Navigate through familiar Mario-themed environments while playing a high-stakes game of Pac-Man, featuring custom models and arcade-style scoring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---5-letters-until-doom', 'N64', 'Paper Mario - 5 Letters until Doom', '2023', 'RPG', 'Independent', '1', 'Story Modification', 'Turn-based RPG with modified story scripts and limited character names.', 'Save the Mushroom Kingdom using only a restricted set of characters.', 'A unique Paper Mario challenge mod with a 5-letter naming restriction.', 'Paper Mario - 5 Letters until Doom offers a fresh narrative twist on the classic RPG. Experience the deep turn-based combat and exploration of the original game with completely revamped dialogue and naming constraints.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---christmas-special', 'N64', 'Paper Mario - Christmas Special', '2023', 'RPG', 'Independent', '1', 'Seasonal Event', 'Turn-based RPG with festive themes, textures, and holiday quests.', 'Complete Christmas-themed missions to bring joy to the Mushroom Kingdom.', 'A heartwarming holiday-themed overhaul of the classic Paper Mario.', 'Paper Mario - Christmas Special is the perfect seasonal mod. Explore a snowy Mushroom Kingdom, complete festive quests, and enjoy a cozy holiday atmosphere in this creative N64 RPG modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---dark-star-edition', 'N64', 'Paper Mario - Dark Star Edition', '2023', 'RPG', 'Independent', '1', 'Story Modification', 'Hardcore turn-based RPG with increased difficulty and new enemies.', 'Survive a much more dangerous Mushroom Kingdom and defeat Bowser.', 'A high-difficulty expansion mod featuring new bosses and mechanics.', 'Paper Mario - Dark Star Edition is built for veterans seeking a challenge. With rebalanced combat, new enemy types, and a higher difficulty curve, it redefines the strategic depth of the N64 original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---dark-star-edition---toadette', 'N64', 'Paper Mario - Dark Star Edition - Toadette', '2023', 'RPG', 'Independent', '1', 'Character Modification', 'Hardcore turn-based RPG featuring Toadette as the main protagonist.', 'Guide Toadette through a high-difficulty version of the Mushroom Kingdom.', 'A Dark Star Edition variant that swaps Mario for Toadette.', 'Paper Mario - Dark Star Edition - Toadette combines extreme difficulty with a fresh protagonist. Master the complex combat systems of the Dark Star mod while playing as everyone’s favorite female Toad.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---master-quest', 'N64', 'Paper Mario - Master Quest', '2023', 'RPG', 'Independent', '1', 'Gameplay Overhaul', 'Extreme turn-based RPG with revamped badges and boss AI.', 'Master the deepest RPG mechanics to overcome grueling new battles.', 'The definitive difficulty mod for Paper Mario, featuring major overhauls.', 'Paper Mario - Master Quest is the ultimate test of strategy. This N64 mod introduces new badges, aggressive enemy AI, and unique encounters that require absolute mastery of the game''s combat engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---master-quest-jr', 'N64', 'Paper Mario - Master Quest Jr', '2023', 'RPG', 'Independent', '1', 'Gameplay Overhaul', 'Turn-based RPG with balanced difficulty for a moderate challenge.', 'Enjoy the Master Quest features with a more accessible learning curve.', 'A "Junior" version of the Master Quest mod for casual players.', 'Paper Mario - Master Quest Jr offers the quality-of-life improvements and new content of the Master Quest mod without the punishing difficulty, making it ideal for players who want a fresh but fair experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario---toadette', 'N64', 'Paper Mario - Toadette', '2023', 'RPG', 'Independent', '1', 'Character Modification', 'Turn-based RPG featuring Toadette as the lead character.', 'Complete the classic Paper Mario quest through the eyes of Toadette.', 'A character-swap mod that replaces Mario with Toadette.', 'Paper Mario - Toadette allows you to play the entire N64 classic with a new perspective. Enjoy the same great story and turn-based combat with Toadette taking the lead in this charming modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-3d-64', 'N64', 'Paper Mario 3D 64', '2023', 'Platform', 'Independent', '1', '3D Platformer', '3D platforming with a paper-thin aesthetic and exploration.', 'Navigate 3D environments using Mario''s paper-inspired abilities.', 'A technical mod exploring the transition of Paper Mario into 3D space.', 'Paper Mario 3D 64 brings a unique visual twist to the console. Explore a world where paper-thin characters navigate a fully realized 3D environment, blending the best of Mario 64 and Paper Mario.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-64-randomizer-preset:-extreme-shuffle', 'N64', 'Paper Mario 64 Randomizer (Preset: Extreme Shuffle)', '2023', 'RPG', 'Independent', '1', 'Randomizer', 'Turn-based RPG with randomized items, enemies, and warp pipes.', 'Adapt to extreme randomness to defeat Bowser in a shuffled world.', 'A chaotic randomizer preset that shuffles almost every game element.', 'Paper Mario 64 Randomizer (Extreme Shuffle) is pure chaos. Every item, enemy encounter, and path is randomized, forcing players to use unconventional strategies to survive this unpredictable N64 journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-64-randomizer-preset:-open-world', 'N64', 'Paper Mario 64 Randomizer (Preset: Open World)', '2023', 'RPG', 'Independent', '1', 'Randomizer', 'Turn-based RPG with non-linear exploration and open-world access.', 'Explore Hyrule in any order you choose to collect the Star Spirits.', 'A randomizer preset that removes the linear progression of the game.', 'Paper Mario 64 Randomizer (Open World) breaks the boundaries of the Mushroom Kingdom. Go anywhere from the start and tackle chapters in any order in this non-linear take on the classic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-multiplayer-12', 'N64', 'Paper Mario Multiplayer 1.2', '2023', 'RPG', 'Independent', '4', 'Multiplayer Modification', 'Turn-based RPG with local multiplayer functionality.', 'Team up with a friend to control Mario and his partners simultaneously.', 'A groundbreaking mod that adds co-op multiplayer to Paper Mario.', 'Paper Mario Multiplayer 1.2 brings a whole new dimension to the game. Share the adventure with a friend on your N64, with one player controlling Mario and the other managing the partners in battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-ttyd64---chapter-5-demo', 'N64', 'Paper Mario TTYD64 - Chapter 5 DEMO', '2023', 'RPG', 'Independent', '1', 'Demo / Prototype', 'Turn-based RPG based on the sequel''s mechanics and setting.', 'Explore the Keelhaul Key area and experience TTYD mechanics on N64.', 'A demo mod bringing The Thousand-Year Door elements to the N64.', 'Paper Mario TTYD64 - Chapter 5 DEMO is an ambitious project that recreates the beloved GameCube sequel''s content using the original N64 engine, featuring new assets and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-ttyd64---toadette', 'N64', 'Paper Mario TTYD64 - Toadette', '2023', 'RPG', 'Independent', '1', 'Character Modification', 'Turn-based RPG with TTYD mechanics featuring Toadette.', 'Test the TTYD64 mechanics while playing as Toadette.', 'A character-specific version of the TTYD64 conversion mod.', 'Paper Mario TTYD64 - Toadette blends the advanced mechanics of the Thousand-Year Door with Toadette''s charm, all running on the classic Nintendo 64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-ttyd64---toadette-wbackground-fix', 'N64', 'Paper Mario TTYD64 - Toadette wBackground Fix', '2023', 'RPG', 'Independent', '1', 'Character Modification', 'Turn-based RPG with TTYD mechanics and optimized graphics.', 'Experience the TTYD64 mod with corrected background textures.', 'A patched version of the TTYD64 mod for better visual stability.', 'Paper Mario TTYD64 - Toadette wBackground Fix ensures a smooth visual experience. Enjoy the TTYD mechanics on N64 without the graphical glitches found in earlier builds of this mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario-ttyd64-v100', 'N64', 'Paper Mario TTYD64 v1.0.0', '2023', 'RPG', 'Independent', '1', 'Full Conversion', 'Turn-based RPG recreating the GameCube classic on N64 hardware.', 'Experience the full mechanics and style of TTYD in the N64 engine.', 'The initial full release of the Thousand-Year Door conversion project.', 'Paper Mario TTYD64 v1.0.0 is a technical marvel. It backports the mechanics, aesthetics, and feel of the GameCube''s TTYD to the Nintendo 64, offering a "what if" scenario for retro fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paper-mario:-cake-chaos', 'N64', 'Paper Mario: Cake Chaos', '2023', 'RPG', 'Independent', '1', 'Challenge Modification', 'Turn-based RPG with a new custom story centered on a cooking disaster.', 'Help Mario solve the mystery of the chaotic cake competition.', 'A custom story mod for Paper Mario with unique dialogue and items.', 'Paper Mario: Cake Chaos is a delicious new adventure. Featuring a custom script and unique scenarios, Mario must navigate a culinary catastrophe in this creative and humorous N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-europe', 'N64', 'Paperboy (Europe)', '1985', 'Action', 'Atari Games', '2', 'Arcade Action', 'Arcade-style bike delivery simulation with obstacle avoidance.', 'Deliver newspapers to subscribers while dodging neighborhood hazards.', 'A classic arcade port where you play as a frantic delivery boy.', 'Paperboy (Europe) brings the hit arcade action to the N64. Navigate suburban streets, toss papers with precision, and avoid everything from dogs to runaway tires in this high-energy delivery sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-usa', 'N64', 'Paperboy (USA)', '1985', 'Action', 'Atari Games', '2', 'Arcade Action', 'Arcade-style bike delivery simulation with obstacle avoidance.', 'Deliver newspapers to subscribers while dodging neighborhood hazards.', 'The North American release of the iconic neighborhood delivery game.', 'Paperboy (USA) features 3D graphics and classic gameplay. Choose your route and try to keep your subscribers happy while surviving the most dangerous suburbs ever seen on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlor!-pro-64---pachinko-jikki-simulation-game-japan', 'N64', 'Parlor! Pro 64 - Pachinko Jikki Simulation Game (Japan)', '1997', 'Simulation', 'Taito', '1', 'Pachinko Simulation', 'Pachinko simulation with advanced machine physics and career modes.', 'Master the professional Pachinko circuit and win big payouts.', 'A professional-grade Pachinko simulator released for the Japanese market.', 'Parlor! Pro 64 - Pachinko Jikki Simulation Game (Japan) is for the serious player. It features high-fidelity recreations of real machines, allowing fans to practice their skills and strategy at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pd-ultraman-battle-collection-64-japan', 'N64', 'PD Ultraman Battle Collection 64 (Japan)', '1999', 'Fighting', 'Bandai', '2', '3D Arena Fighter', 'Turn-based strategy and monster collection with Ultraman characters.', 'Collect Ultraman heroes and battle against giant kaiju monsters.', 'A strategic monster-battle game based on the Ultraman franchise.', 'PD Ultraman Battle Collection 64 (Japan) lets you build the ultimate team of heroes. Use the N64''s power to engage in tactical battles against iconic monsters in this Japan-exclusive strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peachs-christmas-invitation', 'N64', 'Peach''s Christmas Invitation', '2023', 'Adventure', 'Independent', '1', 'Seasonal Event', '3D platforming adventure with a holiday theme and custom maps.', 'Explore Peach''s castle and the surrounding grounds to find gifts.', 'A festive Super Mario 64 mod centered around Princess Peach.', 'Peach''s Christmas Invitation is a cozy holiday mod. Instead of Mario, explore a winter-themed world as Peach, discovering secrets and celebrating the season in this charming N64 hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peachs-fury', 'N64', 'Peach''s Fury', '2023', 'Action', 'Independent', '1', 'Action Adventure', '3D action-platformer inspired by Bowser''s Fury mechanics.', 'Navigate a semi-open world to collect items and stop a rampaging foe.', 'A modern-style Mario mod bringing "Fury" mechanics to the N64.', 'Peach''s Fury is an impressive technical feat. It adapts the open-zone gameplay of modern titles to the N64 engine, featuring Princess Peach in a high-stakes adventure against a dark, powerful force.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguin', 'N64', 'PENGUIN', '2023', 'Platform', 'Independent', '1', 'Experimental Platformer', 'Physics-based puzzle or platforming game featuring penguins.', 'Navigate icy obstacles and reach the goal as a flightless bird.', 'A simple yet addictive homebrew or mod centered on penguin movement.', 'PENGUIN for N64 is a charming exploration of physics and momentum. Slide through icy levels, avoid hazards, and master the art of the waddle in this unique and quirky title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penny-racers-europe', 'N64', 'Penny Racers (Europe)', '1999', 'Racing', 'Mitchell / Ubisoft', '4', 'Arcade Racing', 'Arcade-style racing with miniature cars and combat power-ups.', 'Win races and upgrade your car with wacky parts and weapons.', 'A colorful and fast-paced racer known as Choro Q in Japan.', 'Penny Racers (Europe) offers high-speed fun with customizable miniature cars. Race through imaginative tracks, use power-ups to blast opponents, and collect parts to build the ultimate racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penny-racers-usa', 'N64', 'Penny Racers (USA)', '1999', 'Racing', 'Mitchell / Ubisoft', '4', 'Arcade Racing', 'Arcade-style racing with miniature cars and combat power-ups.', 'Win races and upgrade your car with wacky parts and weapons.', 'The North American version of the customizable miniature car racer.', 'Penny Racers (USA) is all about customization and speed. With dozens of parts to collect and challenging tracks to master, it''s one of the most unique racing experiences on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-europe-enfrdeesit', 'N64', 'Perfect Dark (Europe) (En,Fr,De,Es,It)', '2000', 'Action', 'Rare', '4', 'First-Person Shooter', 'First-person stealth and action shooter with deep mission objectives.', 'Infiltrate data centers and alien bases to stop a global conspiracy.', 'The multi-language European release of Rare''s sci-fi masterpiece.', 'Perfect Dark (Europe) is the spiritual successor to GoldenEye. Take on the role of Joanna Dark in a futuristic world filled with high-tech gadgets, alien threats, and legendary multiplayer modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-japan', 'N64', 'Perfect Dark (Japan)', '2000', 'Action', 'Rare', '4', 'First-Person Shooter', 'First-person stealth and action shooter with deep mission objectives.', 'Infiltrate data centers and alien bases to stop a global conspiracy.', 'The localized Japanese version of the iconic sci-fi FPS.', 'Perfect Dark (Japan) brings Joanna Dark''s epic mission to Japanese players. Experience the deep story and revolutionary "Combat Simulator" in this fully localized N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-usa', 'N64', 'Perfect Dark (USA)', '2000', 'Action', 'Rare', '4', 'First-Person Shooter', 'First-person stealth and action shooter with deep mission objectives.', 'Infiltrate data centers and alien bases to stop a global conspiracy.', 'The definitive North American sci-fi shooter from Rare Ltd.', 'Perfect Dark (USA) set the standard for FPS games on consoles. Featuring a massive campaign and the most customizable multiplayer on the N64, it remains a crowning achievement for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-usa-rev-a', 'N64', 'Perfect Dark (USA) (Rev A)', '2000', 'Action', 'Rare', '4', 'First-Person Shooter', 'First-person stealth and action shooter with deep mission objectives.', 'Infiltrate data centers and alien bases to stop a global conspiracy.', 'An updated revision of the USA version with bug fixes.', 'Perfect Dark (USA) (Rev A) provides the most stable version of Joanna Dark''s mission. Enjoy the same intense action and deep multiplayer with refined performance for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-with-mario-characters---mario', 'N64', 'Perfect Dark with Mario Characters - Mario', '2023', 'Action', 'Independent', '4', 'Character Mod', 'First-person shooter with character-swap models from the Mario series.', 'Complete Joanna Dark''s missions playing as Mario.', 'A creative mod that replaces character models with Mario cast members.', 'Perfect Dark with Mario Characters - Mario is a hilarious crossover. Experience the gritty sci-fi world of Perfect Dark with Mario as the lead agent, featuring custom models and animations on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('perfect-dark-with-mario-characters---peach', 'N64', 'Perfect Dark with Mario Characters - Peach', '2023', 'Action', 'Independent', '4', 'Character Mod', 'First-person shooter with character-swap models from the Mario series.', 'Complete Joanna Dark''s missions playing as Princess Peach.', 'A mod that replaces Joanna Dark with a combat-ready Princess Peach.', 'Perfect Dark with Mario Characters - Peach puts the Princess in the middle of a global conspiracy. Use high-tech weapons and stealth as Peach in this unique and fun modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-european-tour-usa', 'N64', 'PGA European Tour (USA)', '2000', 'Sports', 'Electronic Arts', '4', 'Golf Simulation', 'Realistic golf simulation with professional courses and swing mechanics.', 'Compete in international tournaments to win the PGA European Tour.', 'A professional golf sim featuring real European courses and players.', 'PGA European Tour (USA) brings professional golfing to the N64. Master the wind, terrain, and club selection as you compete across prestigious European courses in this detailed sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-european-tour-golf-europe-enfrdeesit', 'N64', 'PGA European Tour Golf (Europe) (En,Fr,De,Es,It)', '2000', 'Sports', 'Electronic Arts', '4', 'Golf Simulation', 'Realistic golf simulation with multi-language support and pro physics.', 'Win the championship by mastering various holes across Europe.', 'The localized European edition of the pro golf simulation.', 'PGA European Tour Golf (Europe) offers a complete golfing experience for N64. With support for multiple languages, players can experience the tension and strategy of the pro tour on authentic courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pikachuu-genki-de-chuu-japan', 'N64', 'Pikachuu Genki de Chuu (Japan)', '1998', 'Adventure', 'Ambrella', '1', 'Voice Interaction', 'Voice-controlled life simulation using the N64 VRU microphone.', 'Interact and bond with Pikachu to develop a digital friendship.', 'A unique Japan-exclusive game where you talk to Pikachu.', 'Pikachuu Genki de Chuu (Japan) is a landmark title that used voice recognition. Talk to Pikachu, play games, and explore the forest in this charming and innovative Pokemon life simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-64-europe-enfrde', 'N64', 'Pilotwings 64 (Europe) (En,Fr,De)', '1996', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Flight simulation with various vehicles like planes and jetpacks.', 'Complete aerial challenges and earn licenses in different disciplines.', 'A classic flight sim that showcases 3D aerial exploration.', 'Pilotwings 64 (Europe) is an essential N64 experience. Fly through realistic environments, complete precision landing challenges, and explore the skies using hang gliders, gyro-copters, and rocket belts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-64-japan', 'N64', 'Pilotwings 64 (Japan)', '1996', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Flight simulation with various vehicles and pilot training modes.', 'Achieve high scores in flight tests to unlock new islands and gear.', 'The original Japanese release of the iconic flight simulator.', 'Pilotwings 64 (Japan) invited players to the skies of "Holiday Island." Experience the tranquil and challenging gameplay that defined the early era of 3D gaming on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pilotwings-64-usa', 'N64', 'Pilotwings 64 (USA)', '1996', 'Simulation', 'Nintendo', '1', 'Flight Simulation', 'Flight simulation focused on precision maneuvering and aerial stunts.', 'Master the art of flight to earn gold medals in all categories.', 'The North American version of the acclaimed flight sim.', 'Pilotwings 64 (USA) remains a fan favorite for its relaxing yet challenging gameplay. Navigate through rings, pop balloons, and master the physics of flight in this Nintendo 64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('platform-battlefield-v04', 'N64', 'Platform Battlefield v0.4', '2023', 'Platform', 'Independent', '4', 'Competitive Platformer', 'Fighting game platform focused on competitive Smash mechanics.', 'Defeat opponents on a specialized Battlefield-style arena.', 'A specialized mod for Super Smash Bros 64 focusing on competitive play.', 'Platform Battlefield v0.4 is a technical mod designed for the competitive Smash 64 community. It provides a balanced, platform-focused arena perfect for testing skill and frame-perfect combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-as-ganondorf-in-ocarina-of-time', 'N64', 'Play as Ganondorf in Ocarina of Time', '2023', 'Action', 'Nintendo', '1', 'Character Modification', '3D action-adventure with a protagonist model swap and new powers.', 'Conquer Hyrule as the Great King of Evil himself.', 'A creative mod for Ocarina of Time allowing play as Ganondorf.', 'Play as Ganondorf in Ocarina of Time transforms the legendary quest. Utilize Ganondorf’s imposing model and unique animations to experience the world of Hyrule from a darker perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-as-snifit', 'N64', 'Play as Snifit', '2023', 'Action', 'Nintendo', '1', 'Character Modification', '3D platforming with a custom character model in the SM64 engine.', 'Navigate the Mushroom Kingdom as a masked Snifit.', 'A character replacement mod that lets you play as a Snifit.', 'Play as Snifit brings the classic Mario enemy to the forefront. Explore levels and collect stars using this custom character model, adding a quirky twist to the traditional Mario 64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-as-twilight-princess-link-in-ocarina-of-time', 'N64', 'Play as Twilight Princess Link in Ocarina of time', '2023', 'Action', 'Nintendo', '1', 'Character Modification', '3D action-adventure with a modern character model and updated assets.', 'Save the kingdom using the design of Link from Twilight Princess.', 'A visual mod for Ocarina of Time featuring the Twilight Princess style.', 'Play as Twilight Princess Link in Ocarina of time offers a high-fidelity visual update. Experience the N64 classic with the more mature and detailed design of Link from the later GameCube/Wii era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-as-waluigi-in-ocarina-of-time', 'N64', 'Play as Waluigi in Ocarina of Time', '2023', 'Action', 'Nintendo', '1', 'Character Modification', '3D action-adventure featuring the mischievous Waluigi as the hero.', 'Complete the quest of Time using Waluigi''s unique personality and model.', 'A fun Ocarina of Time mod replacing Link with Waluigi.', 'Play as Waluigi in Ocarina of Time is the crossover fans have always wanted. Run, jump, and fight through Hyrule as everyone’s favorite purple trickster in this entertaining N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playable-baby-bowser-in-mario-party-3!', 'N64', 'Playable Baby Bowser in Mario Party 3!', '2000', 'Party', 'Nintendo', '4', 'Character Unlock', 'Virtual board game with turn-based minigames and character swaps.', 'Win the board game and collect stars as Baby Bowser.', 'A mod for Mario Party 3 that makes Baby Bowser a playable contestant.', 'Playable Baby Bowser in Mario Party 3! unlocks the bratty prince for party action. Compete in dozens of minigames and sabotage your friends using this previously unplayable character.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playable-bowser-in-mario-party-3', 'N64', 'Playable Bowser in Mario Party 3', '2000', 'Party', 'Nintendo', '4', 'Character Unlock', 'Virtual board game with turn-based minigames and character swaps.', 'Dominate the board and win minigames as the King of Koopas.', 'A character mod that adds the adult Bowser to the playable roster.', 'Playable Bowser in Mario Party 3 changes the dynamic of the board. Now the boss becomes the player, allowing you to compete against Mario and the gang in the ultimate N64 party game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playable-toad-in-mario-party-3', 'N64', 'Playable Toad in Mario Party 3', '2000', 'Party', 'Nintendo', '4', 'Character Unlock', 'Virtual board game with turn-based minigames and character swaps.', 'Win the superstar title playing as the loyal Mushroom Kingdom servant.', 'A modification that promotes Toad to a fully playable character.', 'Playable Toad in Mario Party 3 finally puts the helpful attendant into the competition. Experience all the boards and minigames with Toad''s unique animations and voice lines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-kart-64', 'N64', 'Pokemon Kart 64', '2023', 'Racing', 'Independent', '4', 'Arcade Racing', 'Arcade kart racing with Pokemon-themed characters and tracks.', 'Win races and use Pokemon abilities to defeat your rivals.', 'A creative racing mod replacing Mario Kart 64 assets with Pokemon.', 'Pokemon Kart 64 is a total conversion for Mario Kart fans. Race as Pikachu, Bulbasaur, and others through themed tracks in this vibrant and competitive Nintendo 64 racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polaris-snocross-usa', 'N64', 'Polaris SnoCross (USA)', '2000', 'Racing', 'Westwood Studios', '8', 'Snowmobile Racing', 'Snowmobile racing with realistic physics and stunt mechanics.', 'Win the SnoCross championship and master icy tracks.', 'An intense snowmobile racing game featuring licensed Polaris vehicles.', 'Polaris SnoCross (USA) brings extreme winter sports to the N64. High-speed racing, massive jumps, and realistic snow physics make this a standout title for fans of outdoor racing and stunts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pomni-in-sm64', 'N64', 'Pomni in SM64', '2023', 'Platform', 'Independent', '1', 'Character Mod', '3D platforming featuring the character Pomni in the SM64 world.', 'Collect stars and explore the castle as the protagonist of Digital Circus.', 'A character-swap mod featuring Pomni from The Amazing Digital Circus.', 'Pomni in SM64 brings modern internet culture to retro gaming. Navigate the classic 3D levels of Mario 64 as Pomni, featuring a custom model and unique animations for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-kart-64', 'N64', 'Pony Kart 64', '2023', 'Racing', 'Independent', '4', 'Arcade Racing', 'Arcade kart racing featuring custom pony characters and vibrant tracks.', 'Cross the finish line first in a world of magic and friendship.', 'A whimsical racing mod inspired by My Little Pony themes.', 'Pony Kart 64 is a colorful and fun racing mod for the N64. Choose your favorite pony and race through imaginative, high-contrast tracks in this lighthearted take on the kart racing genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-league-64-japan', 'N64', 'Power League 64 (Japan)', '1997', 'Sports', 'Hudson Soft', '2', 'Baseball Simulation', 'Baseball simulation with Japanese teams and realistic stats.', 'Lead your team to victory in the Japanese professional leagues.', 'A high-quality baseball sim released exclusively for the Japanese N64.', 'Power League 64 (Japan) offers a deep and authentic baseball experience. Manage rosters, master the pitching mechanics, and experience the excitement of the diamond in this classic sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---lightspeed-rescue-europe', 'N64', 'Power Rangers - Lightspeed Rescue (Europe)', '2000', 'Action', 'Saban Interactive', '2', 'Action Adventure', 'Side-scrolling beat ''em up and vehicular action based on the show.', 'Save the city from monsters using individual Rangers and the Megazord.', 'An action game based on the Power Rangers Lightspeed Rescue season.', 'Power Rangers - Lightspeed Rescue (Europe) lets you suit up as your favorite hero. Battle through various levels, rescue civilians, and pilot powerful Zords to defeat the forces of evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---lightspeed-rescue-usa', 'N64', 'Power Rangers - Lightspeed Rescue (USA)', '2000', 'Action', 'Saban Interactive', '2', 'Action Adventure', 'Side-scrolling beat ''em up and vehicular action based on the show.', 'Stop Diabolico''s monsters and protect Mariner Bay.', 'The North American release of the Lightspeed Rescue action game.', 'Power Rangers - Lightspeed Rescue (USA) delivers fast-paced superhero action. Switch between different Rangers to utilize their unique weapons and save the world in this N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerpuff-girls-the---chemical-x-traction-usa', 'N64', 'Powerpuff Girls, The - Chemical X-Traction (USA)', '2001', 'Action', 'Sennari Interactive', '1', 'Action Platformer', '3D arena fighting game with superpowered abilities and chemical X.', 'Defeat the villains of Townsville using the Powerpuff Girls.', 'A combat-focused game based on the hit Cartoon Network series.', 'Powerpuff Girls, The - Chemical X-Traction (USA) brings Blossom, Bubbles, and Buttercup to the N64. Fight through various arenas to recover Chemical X and defeat Mojo Jojo in this energetic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('premier-manager-64-europe', 'N64', 'Premier Manager 64 (Europe)', '1999', 'Strategy', 'Dinamic Multimedia', '1', 'Management Simulation', 'Football management simulation with deep tactical control.', 'Manage a football club to the top of the league through strategy.', 'A comprehensive soccer management sim for the European market.', 'Premier Manager 64 (Europe) is for the tactical minds. Manage finances, transfers, and matchday strategies to lead your team from the lower divisions to international glory on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-64-japan', 'N64', 'Pro Mahjong Kiwame 64 (Japan)', '1998', 'Board', 'Game Studio', '4', 'Mahjong', 'Traditional Japanese Mahjong simulation with professional rules.', 'Defeat opponents in high-stakes Mahjong matches to become a master.', 'A realistic Mahjong simulator for the Nintendo 64.', 'Pro Mahjong Kiwame 64 (Japan) provides an authentic experience of the classic tile game. Compete against skilled AI opponents in a variety of modes designed for both beginners and experts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-kiwame-64-japan-rev-a', 'N64', 'Pro Mahjong Kiwame 64 (Japan) (Rev A)', '1998', 'Board', 'Game Studio', '4', 'Mahjong', 'Traditional Japanese Mahjong simulation with professional rules.', 'Win the Mahjong tournament using refined strategy and skill.', 'An updated revision of the Kiwame 64 Mahjong simulation.', 'Pro Mahjong Kiwame 64 (Japan) (Rev A) features updated AI and polished gameplay mechanics, offering the most balanced Mahjong experience available for the N64 hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-mahjong-tsuwamono-64---jansou-battle-ni-chousen-japan', 'N64', 'Pro Mahjong Tsuwamono 64 - Jansou Battle ni Chousen (Japan)', '1999', 'Board', 'Koei', '4', 'Mahjong', 'Tactical Mahjong simulation with a focus on parlor-style battles.', 'Rise through the ranks of the Mahjong parlors to become a champion.', 'A competitive Mahjong game focused on the "Battle" aspect of play.', 'Pro Mahjong Tsuwamono 64 (Japan) focuses on the intense, competitive side of Mahjong. Face off against tough characters in a quest to prove your dominance in the local Mahjong scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('projecta95-luigi', 'N64', 'ProjectA95 (Luigi)', '2023', 'Platform', 'Independent', '1', 'Character Mod', 'Experimental technical demo or mod featuring Luigi.', 'Explore early A95 project features using Luigi''s movement.', 'A work-in-progress technical mod centered on Luigi.', 'ProjectA95 (Luigi) is a fascinating look at the technical capabilities of the N64 engine. This build focuses on Luigi, testing physics and environmental interactions in a experimental setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('projecta95-mario', 'N64', 'ProjectA95 (Mario)', '2023', 'Platform', 'Independent', '1', 'Character Mod', 'Experimental technical demo or mod featuring Mario.', 'Explore early A95 project features using Mario''s movement.', 'A work-in-progress technical mod centered on Mario.', 'ProjectA95 (Mario) serves as a foundation for advanced N64 modding. Test new shaders, movements, and level designs in this early-access look at the ProjectA95 engine''s potential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pumpkin-hills', 'N64', 'Pumpkin Hills', '2023', 'Adventure', 'Independent', '1', 'Exploration Mod', '3D platforming in a spooky, autumn-themed environment.', 'Collect items and navigate the heights of the Pumpkin Hill area.', 'A recreation of the famous Sonic Adventure 2 level in the N64 engine.', 'Pumpkin Hills brings a piece of Dreamcast history to the N64. Explore this iconic spooky landscape, complete with custom textures and music, rebuilt specifically for Nintendo''s 3D platforming engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-4---puyo-puyon-party-japan', 'N64', 'Puyo Puyo 4 - Puyo Puyon Party (Japan)', '1999', 'Puzzle', 'Compile', '4', 'Competitive Puzzle', 'Fast-paced tile-matching puzzle game with a magical theme.', 'Defeat opponents by chaining together Puyo combos.', 'The fourth major entry in the Puyo Puyo puzzle series.', 'Puyo Puyo 4 - Puyo Puyon Party (Japan) is a vibrant and addictive puzzle game. Featuring a large cast of characters and deep combo mechanics, it’s one of the most polished puzzle titles on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-sun-64-english', 'N64', 'Puyo Puyo Sun 64 (English)', '1997', 'Puzzle', 'Compile', '4', 'Competitive Puzzle', 'Fast-paced tile-matching puzzle game with an English translation.', 'Use sun-themed mechanics to overwhelm your puzzle rivals.', 'An English-translated version of the fan-favorite puzzle game.', 'Puyo Puyo Sun 64 (English) allows western fans to enjoy the deep mechanics of the "Sun" series. Chain combos and drop sun blocks on your opponents in this highly accessible puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-sun-64-japan', 'N64', 'Puyo Puyo Sun 64 (Japan)', '1997', 'Puzzle', 'Compile', '4', 'Competitive Puzzle', 'Fast-paced tile-matching puzzle game with sun power-ups.', 'Outsmart the computer or friends in competitive puzzle matches.', 'The original Japanese release of the third Puyo Puyo game.', 'Puyo Puyo Sun 64 (Japan) introduced the Sun Puyo mechanic, adding a new layer of strategy to the classic "match four" gameplay. It features bright graphics and a humorous story mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble-64-japan', 'N64', 'Puzzle Bobble 64 (Japan)', '1999', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble-shooting puzzle game with a focus on matching colors.', 'Clear all bubbles from the screen to progress to the next stage.', 'A Japanese version of the classic Bust-a-Move puzzle series.', 'Puzzle Bobble 64 (Japan) is the ultimate pick-up-and-play title. Aim your launcher, match colored bubbles, and enjoy the charming characters and music of this legendary puzzle franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quake-64-europe', 'N64', 'Quake 64 (Europe)', '1998', 'Action', 'Midway / Lobotomy Software', '4', 'First-Person Shooter', 'First-person shooter with atmospheric lighting and fast-paced combat.', 'Navigate dark corridors to find the exit while slaying demonic entities.', 'A port of the PC classic optimized for N64 with real-time lighting.', 'Quake 64 (Europe) brings the dark, gothic world of the original FPS to the console. Experience intense action and eerie atmospheres as you fight through hordes of enemies in this definitive N64 port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quake-64-usa', 'N64', 'Quake 64 (USA)', '1998', 'Action', 'Midway / Lobotomy Software', '4', 'First-Person Shooter', 'First-person shooter with atmospheric lighting and fast-paced combat.', 'Defeat the ancient evil Shub-Niggurath and survive the slipgates.', 'The North American version of the legendary dark fantasy FPS.', 'Quake 64 (USA) features exclusive colored lighting effects and smooth gameplay. Battle through multidimensional fortresses and master a variety of weapons in this classic 3D shooter experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quake-ii-europe', 'N64', 'Quake II (Europe)', '1999', 'Action', 'Raster Productions / Id Software', '4', 'First-Person Shooter', 'Sci-fi first-person shooter with mission-based objectives.', 'Infiltrate the Strogg home planet and deactivate their planetary defenses.', 'A console-exclusive mission set in the Quake II universe.', 'Quake II (Europe) offers a different experience from the PC version, featuring custom levels designed for the N64. Fight the biomechanical Strogg army in this high-octane sci-fi shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quake-ii-usa', 'N64', 'Quake II (USA)', '1999', 'Action', 'Raster Productions / Id Software', '4', 'First-Person Shooter', 'Sci-fi first-person shooter with mission-based objectives.', 'Survive the alien onslaught and stop the Strogg invasion of Earth.', 'The acclaimed North American sci-fi shooter with 4-player multiplayer.', 'Quake II (USA) is a powerhouse of N64 action. With a dedicated campaign and legendary split-screen multiplayer modes, it remains one of the most technically impressive shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quest-64-usa', 'N64', 'Quest 64 (USA)', '1998', 'RPG', 'Imagineer', '1', 'Action RPG', 'Traditional 3D turn-based RPG with elemental magic systems.', 'Collect the elemental jewels to save the world of Celtear.', 'A colorful fantasy RPG and one of the few of its kind on N64.', 'Quest 64 (USA) follows the journey of Brian, a young apprentice mage. Explore a vast 3D world, level up your elemental spells, and engage in a unique turn-based combat system without traditional menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('racing-simulation-2-germany', 'N64', 'Racing Simulation 2 (Germany)', '1999', 'Racing', 'Titus Interactive', '2', 'Driving Simulation', 'Professional Formula 1 and grand tour racing simulation.', 'Master realistic driving physics to win the world championship.', 'A technical racing sim known for its realism in the German market.', 'Racing Simulation 2 (Germany) provides an authentic driving experience for N64. Tweak your car''s settings, master the racing lines, and compete against the best drivers in this deep simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rainbow-blast', 'N64', 'Rainbow Blast', '2023', 'Puzzle', 'Independent', '2', 'Arcade Puzzle', '3D platforming with vibrant colors and fast-paced movement.', 'Navigate through bright levels to collect items and reach the goal.', 'A colorful and cheerful modification for the Super Mario 64 engine.', 'Rainbow Blast is a vibrant mod that emphasizes speed and visual flair. Explore custom-designed levels filled with rainbow-themed challenges and creative platforming obstacles on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rakuga-kids-europe', 'N64', 'Rakuga Kids (Europe)', '1998', 'Fighting', 'Treasure', '4', 'Arcade Fighter', '2D fighting game with a hand-drawn, sketch-like aesthetic.', 'Defeat opponents in a creative tournament of living drawings.', 'A unique 2D brawler where characters look like schoolroom doodles.', 'Rakuga Kids (Europe) is a cult classic known for its imaginative art style. Choose from a variety of sketch-inspired fighters and master their quirky moves in this charming N64 fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rakuga-kids-japan', 'N64', 'Rakuga Kids (Japan)', '1998', 'Fighting', 'Treasure', '4', 'Arcade Fighter', '2D fighting game with a hand-drawn, sketch-like aesthetic.', 'Battle against other "doodle" creatures to prove your artistic dominance.', 'The original Japanese release of the quirky drawing-themed fighter.', 'Rakuga Kids (Japan) showcases the creativity of N64''s 2D capabilities. With fluid animations and a whimsical soundtrack, it offers a fighting experience unlike any other on the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rally-99-japan', 'N64', 'Rally ''99 (Japan)', '1999', 'Racing', 'Taito', '2', 'Rally Racing', 'Off-road rally racing with realistic terrain and drift mechanics.', 'Complete various rally stages in the fastest time possible.', 'A Japan-exclusive rally sim featuring licensed vehicles and tracks.', 'Rally ''99 (Japan) brings the grit of professional rally racing to your console. Navigate through dirt, snow, and asphalt tracks while managing your car''s handling in this challenging racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rally-challenge-2000-usa', 'N64', 'Rally Challenge 2000 (USA)', '1999', 'Racing', 'Atari / Reflections', '2', 'Rally Racing', 'High-speed rally racing across diverse global environments.', 'Win the championship by conquering extreme weather and terrain.', 'A fast-paced rally game with an emphasis on arcade-style fun.', 'Rally Challenge 2000 (USA) takes players across the world, from the Amazon to the Himalayas. Experience responsive controls and varied track conditions in this exciting N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage---world-tour-europe', 'N64', 'Rampage - World Tour (Europe)', '1997', 'Action', 'Midway', '4', 'Arcade Destruction', 'City-smashing action with giant monsters and destructible environments.', 'Destroy famous landmarks while avoiding the military.', 'A fun port of the arcade hit where you play as the monsters.', 'Rampage - World Tour (Europe) lets you wreak havoc on a global scale. Play as George, Lizzie, or Ralph as you smash buildings and eat tourists in this classic destruction simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage---world-tour-usa', 'N64', 'Rampage - World Tour (USA)', '1997', 'Action', 'Midway', '4', 'Arcade Destruction', 'City-smashing action with giant monsters and destructible environments.', 'Level cities across the globe to complete the world tour.', 'The North American arcade port of giant monster mayhem.', 'Rampage - World Tour (USA) is pure arcade fun on the N64. Team up with friends in 3-player co-op to bring down skyscrapers and survive the military''s counter-offensive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage-2---universal-tour-europe', 'N64', 'Rampage 2 - Universal Tour (Europe)', '1999', 'Action', 'Midway', '4', 'Arcade Destruction', 'Sci-fi destruction action with new monsters and planetary travel.', 'Save the original monsters by destroying cities across the universe.', 'The sequel to World Tour, featuring an expanded roster and story.', 'Rampage 2 - Universal Tour (Europe) takes the destruction to outer space. Command new monsters, explore alien worlds, and continue the addictive loop of smashing everything in sight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage-2---universal-tour-usa', 'N64', 'Rampage 2 - Universal Tour (USA)', '1999', 'Action', 'Midway', '4', 'Arcade Destruction', 'Sci-fi destruction action with new monsters and planetary travel.', 'Conquer Earth and beyond to rescue your captured monster friends.', 'The North American version of the intergalactic destruction sequel.', 'Rampage 2 - Universal Tour (USA) expands the classic formula with new characters like Boris the Rhino. Smash your way through more levels and larger environments in this chaotic N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rat-attack!-europe-enfrdeesitnl', 'N64', 'Rat Attack! (Europe) (En,Fr,De,Es,It,Nl)', '1999', 'Platform', 'Nintendo', '1', '3D Platformer', 'Top-down puzzle action game involving trapping and clearing pests.', 'Use high-tech gadgets to capture a variety of mischievous rats.', 'A unique and colorful puzzle game with multi-language support.', 'Rat Attack! (Europe) challenges your reflexes and strategic thinking. Choose your feline hero and use "Erace-a-Zones" to clear rooms of pests in this vibrant and frantic N64 puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rat-attack!-usa-enfrdeesitnl', 'N64', 'Rat Attack! (USA) (En,Fr,De,Es,It,Nl)', '1999', 'Platform', 'Nintendo', '1', '3D Platformer', 'Top-down puzzle action game involving trapping and clearing pests.', 'Prevent the rat invasion by clearing all levels of the rodent threat.', 'The North American release of the strategic cat-vs-rat puzzle game.', 'Rat Attack! (USA) offers addictive puzzle gameplay for all ages. With multiple playable characters and increasingly difficult levels, it''s a hidden gem of strategy on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-2---the-great-escape-europe-enfrdeesit', 'N64', 'Rayman 2 - The Great Escape (Europe) (En,Fr,De,Es,It)', '1999', 'Platform', 'Ubisoft', '1', '3D Platformer', '3D platformer featuring a wide range of movement and powers.', 'Collect Lums and free the Teensies to save the Glade of Dreams.', 'A critically acclaimed 3D adventure with deep atmosphere and lore.', 'Rayman 2 - The Great Escape (Europe) is often cited as one of the best platformers on the system. Explore lush environments and use Rayman''s unique abilities to defeat the Robo-Pirates.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rayman-2---the-great-escape-usa-enfrdeesit', 'N64', 'Rayman 2 - The Great Escape (USA) (En,Fr,De,Es,It)', '1999', 'Platform', 'Ubisoft', '1', '3D Platformer', '3D platformer featuring a wide range of movement and powers.', 'Save the world from Admiral Razorbeard and his mechanical army.', 'The definitive North American 3D adventure featuring Rayman.', 'Rayman 2 - The Great Escape (USA) delivers a cinematic platforming experience. With smooth controls and imaginative level design, it is a must-play title for every N64 owner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('razmoket-les---la-chasse-aux-tresors-france', 'N64', 'Razmoket, Les - La Chasse aux Tresors (France)', '1999', 'Adventure', 'Ubisoft', '1', 'Action Adventure', '3D adventure and minigame collection based on the Rugrats show.', 'Explore various themed worlds to find hidden treasures.', 'The French version of the popular Rugrats: Treasure Hunt game.', 'Razmoket, Les - La Chasse aux Tresors brings the beloved Nickelodeon characters to the N64. Join Tommy, Chuckie, and the gang in a series of board-game style levels and fun challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('razor-freestyle-scooter-usa', 'N64', 'Razor Freestyle Scooter (USA)', '2000', 'Sports', 'Titus Interactive', '1', 'Extreme Sports', 'Extreme sports simulation featuring freestyle scooter tricks.', 'Perform stunts and complete objectives to unlock new gear and riders.', 'A fast-paced scooter game in the vein of the Tony Hawk series.', 'Razor Freestyle Scooter (USA) lets you hit the pavement with style. Master grinds, flips, and spins across urban environments to earn high scores and become a pro scooter rider on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('razor-sword-improvement', 'N64', 'Razor Sword Improvement', '2023', 'Action', 'Independent', '1', 'Gameplay Modification', '3D action-adventure with an emphasis on combat mechanics.', 'Complete the quest using an upgraded and more powerful sword.', 'A gameplay modification for Ocarina of Time enhancing the Razor Sword.', 'Razor Sword Improvement is a targeted mod that makes the Razor Sword a more viable and durable weapon. Enjoy the classic adventure with improved combat balance and equipment utility.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('re-volt-europe-enfrdees', 'N64', 'Re-Volt (Europe) (En,Fr,De,Es)', '1999', 'Racing', 'Acclaim Studios London', '4', 'Arcade Racing', 'Radio-controlled car racing with unique physics and weapons.', 'Win races against other RC cars on oversized household tracks.', 'A cult favorite racer known for its challenging physics and charm.', 'Re-Volt (Europe) puts you in control of miniature RC cars. Race through supermarkets, toy stores, and neighborhoods, using pick-ups to gain an advantage in this high-speed N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('re-volt-usa', 'N64', 'Re-Volt (USA)', '1999', 'Racing', 'Acclaim Studios London', '4', 'Arcade Racing', 'Radio-controlled car racing with unique physics and weapons.', 'Become the champion of the RC world by mastering every track.', 'The North American version of the miniature car racing phenomenon.', 'Re-Volt (USA) features a huge roster of cars and a robust track editor. Experience the unique handling of RC vehicles as you navigate creative environments in this beloved racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ready-2-rumble-boxing---round-2-usa', 'N64', 'Ready 2 Rumble Boxing - Round 2 (USA)', '2000', 'Sports', 'Midway', '2', 'Arcade Boxing', 'Arcade-style boxing with exaggerated characters and special moves.', 'Win the championship belt by knocking out a roster of wacky boxers.', 'The high-energy sequel to the hit arcade boxing game.', 'Ready 2 Rumble Boxing - Round 2 (USA) brings more flair and "rumble" to the ring. Featuring new characters and even celebrities, it’s a fast-paced and humorous take on the sport for N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ready-2-rumble-boxing-europe-enfrde', 'N64', 'Ready 2 Rumble Boxing (Europe) (En,Fr,De)', '1998', 'Sports', 'Midway', '2', 'Arcade Boxing', 'Arcade-style boxing with exaggerated characters and special moves.', 'Rise through the ranks of the professional boxing circuit.', 'The original arcade-style boxer that introduced the "Rumble" mechanic.', 'Ready 2 Rumble Boxing (Europe) is all about timing and personality. Choose your boxer, taunt your opponent, and build your meter to unleash devastating combos in this classic N64 fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ready-2-rumble-boxing-usa', 'N64', 'Ready 2 Rumble Boxing (USA)', '1998', 'Sports', 'Midway', '2', 'Arcade Boxing', 'Arcade-style boxing with exaggerated characters and special moves.', 'Defeat a colorful cast of opponents to become the world champ.', 'The North American release of the iconic, stylish boxing game.', 'Ready 2 Rumble Boxing (USA) set the standard for arcade sports on the N64. With its vibrant graphics and accessible controls, it offers endless fun for both solo players and friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('red-baby-bowser-in-mario-party-3', 'N64', 'Red Baby Bowser in Mario Party 3', '2023', 'Party', 'Nintendo', '4', 'Character Modification', 'Virtual board game with turn-based minigames and character swaps.', 'Win the board game using a custom-colored Red Baby Bowser.', 'A character color mod for Mario Party 3 featuring a red variant.', 'Red Baby Bowser in Mario Party 3 adds a visual twist to the roster. Play through all your favorite boards and minigames with this unique red-tinted version of the Koopa prince.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('red-bird-from-angry-birds-over-toad', 'N64', 'Red bird from Angry Birds over Toad', '2023', 'Party', 'Independent', '4', 'Character Modification', '3D platforming with a custom character model swap.', 'Explore the Mushroom Kingdom as the iconic Red Bird from Angry Birds.', 'A humorous mod that replaces Toad with Red from Angry Birds.', 'Red bird from Angry Birds over Toad brings a mobile gaming icon to the N64. Navigate the world of Mario 64 with this custom bird model, adding a funny crossover element to the classic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-2-europe-enfr', 'N64', 'Resident Evil 2 (Europe) (En,Fr)', '1999', 'Survival Horror', 'Capcom', '1', 'Survival Horror', 'Survival horror with resource management and puzzle solving.', 'Survive the zombie outbreak in Raccoon City and escape alive.', 'A technical masterpiece and the European release of the horror classic.', 'Resident Evil 2 (Europe) is a marvel of N64 engineering. Experience the terrifying journey of Leon and Claire on a single cartridge, featuring atmospheric FMVs and deep, branching survival horror gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-2-usa', 'N64', 'Resident Evil 2 (USA)', '1999', 'Survival Horror', 'Capcom', '1', 'Survival Horror', 'Survival horror with resource management and puzzle solving.', 'Uncover the truth behind the Umbrella Corporation and survive.', 'The definitive North American version of the iconic horror sequel.', 'Resident Evil 2 (USA) brought the horror genre to new heights on the N64. Manage your limited ammo, solve intricate puzzles, and face off against terrifying creatures in the dark streets of Raccoon City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('resident-evil-2-usa-rev-a', 'N64', 'Resident Evil 2 (USA) (Rev A)', '1999', 'Survival Horror', 'Capcom', '1', 'Survival Horror', 'Survival horror with resource management and puzzle solving.', 'Navigate the horrors of Raccoon City with improved stability.', 'An updated revision of the USA version with minor bug fixes.', 'Resident Evil 2 (USA) (Rev A) provides the most polished version of this horror landmark. Enjoy the same intense story and "Zapping System" with refined performance for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('retro-mario-time', 'N64', 'Retro Mario Time', '2023', 'Platform', 'Independent', '1', 'Time Challenge Platformer', '3D platforming with retro-styled textures and classic sound effects.', 'Collect Power Stars in levels redesigned with a nostalgic 8-bit aesthetic.', 'A Super Mario 64 mod that blends N64 gameplay with NES-era visuals.', 'Retro Mario Time brings a nostalgic twist to the 64-bit era. Explore classic environments reimagined with 8-bit textures and retro sound design, offering a unique crossover experience for long-time Nintendo fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('return-to-yoshis-island-64-demo', 'N64', 'Return to Yoshi''s Island 64 DEMO', '2023', 'Platform', 'Independent', '1', 'Demo / Fan Sequel', '3D platforming with a focus on egg-throwing and exploration.', 'Navigate through custom tropical levels to rescue Yoshi''s friends.', 'A high-quality WIP demo of Yoshi''s Island reimagined in 3D.', 'Return to Yoshi''s Island 64 DEMO is an ambitious project that brings the charm of the SNES classic into the 3D world. Experience unique egg-tossing mechanics and vibrant level design in this promising N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-64-europe', 'N64', 'Road Rash 64 (Europe)', '1999', 'Racing', 'Pacific Coast Power & Light', '2', 'Arcade Motorcycle Racing', 'Vehicular combat racing with hand-to-hand weapons on motorcycles.', 'Win illegal street races while fighting off rivals and avoiding the police.', 'The European version of the brutal, high-speed motorcycle combat game.', 'Road Rash 64 (Europe) delivers high-octane violence on two wheels. Kick, punch, and use clubs to knock opponents off their bikes while navigating dangerous traffic and winding roads in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-64-usa', 'N64', 'Road Rash 64 (USA)', '1999', 'Racing', 'Pacific Coast Power & Light', '2', 'Arcade Motorcycle Racing', 'Vehicular combat racing with hand-to-hand weapons on motorcycles.', 'Finish in first place by any means necessary in the street racing circuit.', 'The North American release of the iconic motorcycle brawler.', 'Road Rash 64 (USA) is the definitive motorcycle combat experience. Featuring a robust physics engine and hilarious wipeouts, it offers a perfect blend of arcade racing and chaotic combat for up to four players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roadsters-europe-enfrdeesitnl', 'N64', 'Roadsters (Europe) (En,Fr,De,Es,It,Nl)', '1999', 'Racing', 'Titus Interactive', '2', 'Arcade Racing', 'Arcade-style racing featuring licensed open-top sports cars.', 'Win championships to unlock new cars and progress through divisions.', 'A stylish racer focused on convertible cars and diverse tracks.', 'Roadsters (Europe) offers a sleek racing experience with a variety of luxury convertibles. Master the handling across different weather conditions and terrains to become the ultimate champion in this multi-language release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roadsters-usa-enfres', 'N64', 'Roadsters (USA) (En,Fr,Es)', '1999', 'Racing', 'Titus Interactive', '2', 'Arcade Racing', 'Arcade-style racing featuring licensed open-top sports cars.', 'Climb the ranks of the Roadster Trophy across multiple continents.', 'The North American version of the fast-paced convertible racing game.', 'Roadsters (USA) combines arcade speed with a wide selection of customizable cars. Compete in multi-round tournaments and enjoy the smooth graphics and responsive controls that define this N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robot-poncots-64---7tsu-no-umi-no-caramel-japan', 'N64', 'Robot Poncots 64 - 7tsu no Umi no Caramel (Japan)', '1999', 'RPG', 'RED Entertainment', '1', 'Monster RPG', 'Monster-collecting RPG with turn-based robot battles.', 'Collect and upgrade robots to become the top master of the seven seas.', 'A Japan-exclusive RPG similar to Pokemon but with customizable robots.', 'Robot Poncots 64 (Japan) is a deep RPG where you collect, customize, and battle robotic creatures. Explore a vast world and manage your "Robopon" team to conquer the Seven Seas in this charming title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotech---crystal-dreams-usa-proto', 'N64', 'Robotech - Crystal Dreams (USA) (Proto)', '1999', 'Action', 'Neverland / Bandai', '1', 'Prototype', '3D space combat simulation with exploration and resource management.', 'Protect the SDF-1 and defend Earth from Zentraedi forces.', 'An unreleased prototype of a high-ambition Robotech flight sim.', 'Robotech - Crystal Dreams (USA) (Proto) is a rare look at a cancelled N64 project. Engage in space dogfights and explore open environments in this ambitious title based on the beloved mecha anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotron-64-europe', 'N64', 'Robotron 64 (Europe)', '1998', 'Action', 'Midway', '2', 'Arcade Shooter', 'Twin-stick shooter with fast-paced waves of robotic enemies.', 'Save the last human family from the onslaught of the Robotrons.', 'An updated 3D version of the classic arcade shooter for Europe.', 'Robotron 64 (Europe) brings the frantic energy of the arcade original to the N64. Face hundreds of enemies at once and test your reflexes in this pulse-pounding, techno-fueled action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robotron-64-usa', 'N64', 'Robotron 64 (USA)', '1998', 'Action', 'Midway', '2', 'Arcade Shooter', 'Twin-stick shooter with fast-paced waves of robotic enemies.', 'Clear all levels and protect humanity from robotic extinction.', 'The North American release of the high-speed arcade revival.', 'Robotron 64 (USA) features intense gameplay and a pounding soundtrack. With dozens of enemies on screen and a variety of power-ups, it''s one of the most challenging and satisfying shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket---robot-on-wheels-europe-enfrde', 'N64', 'Rocket - Robot on Wheels (Europe) (En,Fr,De)', '1999', 'Platform', 'Sucker Punch Productions', '1', '3D Platformer', 'Physics-based 3D platforming with a customizable robot hero.', 'Solve puzzles and collect tickets to save the Whoopee World park.', 'A creative platformer featuring a unique physics engine.', 'Rocket - Robot on Wheels (Europe) is a hidden gem from Sucker Punch. Use a tractor beam to manipulate objects and solve complex puzzles in this highly innovative and charming 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocket---robot-on-wheels-usa', 'N64', 'Rocket - Robot on Wheels (USA)', '1999', 'Platform', 'Sucker Punch Productions', '1', '3D Platformer', 'Physics-based 3D platforming with a customizable robot hero.', 'Navigate the theme park and stop the evil Jojo the Raccoon.', 'The North American version of the physics-driven platformer.', 'Rocket - Robot on Wheels (USA) showcased impressive physics for its time. Experience varied levels, from snowy mountains to futuristic cities, using Rocket''s unique mechanical abilities to save the day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rockman-dash---hagane-no-boukenshin-japan', 'N64', 'Rockman Dash - Hagane no Boukenshin (Japan)', '1997', 'Action', 'Capcom', '1', 'Action Adventure', 'Third-person action-adventure with exploration and combat.', 'Explore an island of ruins to find ancient treasures and parts.', 'The Japanese version of the game known as Mega Man Legends.', 'Rockman Dash (Japan) brings the legendary Blue Bomber into a fully 3D world. Explore the ruins of Kattelox Island, fight massive bosses, and enjoy a deep, character-driven story on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rosalina-in-mario-party-3-over-mario', 'N64', 'Rosalina in Mario Party 3 over Mario', '2023', 'Party', 'Nintendo', '4', 'Character Modification', 'Virtual board game with character swap and custom animations.', 'Win the Mario Party boards playing as the protector of the stars.', 'A mod that replaces Mario with Rosalina in Mario Party 3.', 'Rosalina in Mario Party 3 over Mario brings the fan-favorite Galaxy princess to the retro party. Enjoy the classic board game experience with Rosalina''s custom model and icons, fully integrated into the N64 engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rosalina-in-mario-party-3-over-peach', 'N64', 'Rosalina in Mario Party 3 over Peach', '2023', 'Party', 'Nintendo', '4', 'Character Modification', 'Virtual board game with character swap and custom animations.', 'Compete for the title of Super Star using Rosalina''s model.', 'A mod that replaces Peach with Rosalina in Mario Party 3.', 'Rosalina in Mario Party 3 over Peach allows players to swap the classic princess for Rosalina. This cosmetic modification updates the roster while keeping the legendary minigame gameplay intact.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rr64---ridge-racer-64-europe', 'N64', 'RR64 - Ridge Racer 64 (Europe)', '2000', 'Racing', 'Namco', '2', 'Arcade Racing', 'High-speed arcade racing with drift-heavy mechanics.', 'Win the Grand Prix by mastering high-speed turns and drafting.', 'The European version of the classic Namco racing franchise.', 'RR64 - Ridge Racer 64 (Europe) features the signature drift gameplay the series is known for. Race through diverse tracks with smooth 60fps performance and unlock a variety of high-performance vehicles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rr64---ridge-racer-64-usa', 'N64', 'RR64 - Ridge Racer 64 (USA)', '2000', 'Racing', 'Namco', '2', 'Arcade Racing', 'High-speed arcade racing with drift-heavy mechanics.', 'Become the king of the Ridge across various racing circuits.', 'The North American release of Namco''s premier N64 racer.', 'RR64 - Ridge Racer 64 (USA) is a technical showcase for the console. With tight controls, legendary music, and intense 4-player split-screen modes, it remains a top-tier racing experience for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rtl-world-league-soccer-2000-germany', 'N64', 'RTL World League Soccer 2000 (Germany)', '2000', 'Sports', 'Gremlin Interactive', '2', 'Soccer Simulation', 'Football management and simulation with updated 2000 rosters.', 'Lead your soccer team to the world championship through strategy.', 'A localized German soccer game featuring deep management options.', 'RTL World League Soccer 2000 (Germany) provides a comprehensive look at the world of football. Manage your team''s tactics and play through realistic matches in this late-era N64 sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---die-grosse-schatzsuche-germany', 'N64', 'Rugrats - Die grosse Schatzsuche (Germany)', '1999', 'Adventure', 'Software Creations', '1', 'Adventure Platformer', 'Virtual board game with themed minigames based on the cartoon.', 'Find the most hidden treasures to win the game as a baby.', 'The German version of the Rugrats: Treasure Hunt adventure.', 'Rugrats - Die grosse Schatzsuche brings Tommy and friends to life. Navigate through board-game style levels inspired by the show''s episodes and compete in fun, child-friendly minigames.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---scavenger-hunt-usa', 'N64', 'Rugrats - Scavenger Hunt (USA)', '1999', 'Adventure', 'Software Creations', '1', 'Adventure Platformer', 'Board-game adventure with competitive scavenger hunt mechanics.', 'Collect all the required items across various themed maps.', 'A board game style Rugrats title for the North American market.', 'Rugrats - Scavenger Hunt (USA) features three distinct game boards. Play as your favorite Rugrat and use special cards to sabotage your friends in this interactive and colorful N64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats---treasure-hunt-europe', 'N64', 'Rugrats - Treasure Hunt (Europe)', '1999', 'Adventure', 'Software Creations', '1', 'Adventure Platformer', 'Virtual board game with themed minigames and exploration.', 'Explore the world of the Rugrats to find hidden objects and toys.', 'The European multi-language release of the Treasure Hunt game.', 'Rugrats - Treasure Hunt (Europe) is a perfect title for younger fans. Follow the babies on their imaginative adventures and compete in simple but engaging minigames across several unique locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats-in-paris---the-movie-europe', 'N64', 'Rugrats in Paris - The Movie (Europe)', '2000', 'Platform', 'THQ', '2', '3D Platformer', '3D adventure and minigame collection based on the feature film.', 'Find the missing Reptar pieces in the Euro-Reptarland park.', 'The European version of the cinematic Rugrats adventure.', 'Rugrats in Paris - The Movie (Europe) takes the babies to France. Explore the theme park, play a variety of carnival-style minigames, and relive the events of the movie in this vibrant 3D title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rugrats-in-paris---the-movie-usa', 'N64', 'Rugrats in Paris - The Movie (USA)', '2000', 'Platform', 'THQ', '2', '3D Platformer', '3D adventure and minigame collection based on the feature film.', 'Help the Rugrats find Chuckie a new mom and fix Reptar.', 'The North American release of the movie-based 3D game.', 'Rugrats in Paris - The Movie (USA) features a large hub world and numerous activities. Collect tickets to unlock new areas and enjoy the humor and charm of the hit Nickelodeon film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ruinous-shards', 'N64', 'Ruinous Shards', '2023', 'Action', 'Independent', '1', 'Action RPG', '3D platforming with custom levels and challenging puzzles.', 'Collect the scattered shards within a mysterious, ruined world.', 'A creative ROM hack for Super Mario 64 featuring new environments.', 'Ruinous Shards is a unique modification that offers a darker, more atmospheric take on Mario 64. Explore decaying structures and solve environmental puzzles in this custom-built N64 experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rush-2---extreme-racing-usa-europe-enfrdeesitnl', 'N64', 'Rush 2 - Extreme Racing USA (Europe) (En,Fr,De,Es,It,Nl)', '1998', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-octane arcade racing with massive jumps and stunts.', 'Win races across the USA while performing extreme stunts for points.', 'The European release of the over-the-top stunt racing sequel.', 'Rush 2 - Extreme Racing USA (Europe) is all about speed and airtime. Navigate secret shortcuts, master the dedicated stunt mode, and customize your car in this high-energy N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rush-2---extreme-racing-usa-usa', 'N64', 'Rush 2 - Extreme Racing USA (USA)', '1998', 'Racing', 'Midway', '4', 'Arcade Racing', 'High-octane arcade racing with massive jumps and stunts.', 'Explore every hidden path and win the extreme racing circuit.', 'The definitive North American version of the iconic stunt racer.', 'Rush 2 - Extreme Racing USA (USA) features some of the most creative track designs on the N64. From Alcatraz to Las Vegas, experience pure arcade thrill with the system''s best stunt physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scars-europe-enfrde', 'N64', 'S.C.A.R.S. (Europe) (En,Fr,De)', '1998', 'Action', 'Vivid Image', '2', 'Combat Racing', 'Combat racing with animal-inspired vehicles and futuristic weapons.', 'Win the S.C.A.R.S. tournament by outdriving and outshooting rivals.', 'A unique combat racer featuring vehicles that look like animals.', 'S.C.A.R.S. (Europe) combines racing with tactical combat. Each animal-car has unique stats; use a variety of weapons to slow down opponents and claim victory in this futuristic arena racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scars-usa', 'N64', 'S.C.A.R.S. (USA)', '1998', 'Action', 'Vivid Image', '2', 'Combat Racing', 'Combat racing with animal-inspired vehicles and futuristic weapons.', 'Destroy your opponents and finish first in the global circuit.', 'The North American release of the vehicular combat racing game.', 'S.C.A.R.S. (USA) offers a distinctive visual style and fast-paced gameplay. Master the "Super Computer Animal Racing Simulator" and dominate the tracks using animal-themed weaponry and speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sad-sponge-64', 'N64', 'Sad Sponge 64', '2023', 'Platform', 'Independent', '1', 'Experimental Platformer', '3D platforming with a custom character model and melancholy theme.', 'Navigate a surreal world as a depressed version of SpongeBob.', 'A quirky and atmospheric mod for the Super Mario 64 engine.', 'Sad Sponge 64 is a surreal modification that places a "sad" SpongeBob character into custom environments. Experience a unique, slightly meme-inspired adventure with custom textures and a somber tone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saikyou-habu-shougi-japan', 'N64', 'Saikyou Habu Shougi (Japan)', '1998', 'Board', 'Bottom Up', '2', 'Shogi', 'Traditional Japanese Shougi simulation with professional AI.', 'Defeat Shougi masters to prove your strategic dominance.', 'A realistic Shougi simulator and an early N64 launch title.', 'Saikyou Habu Shougi (Japan) features the expertise of Shougi legend Yoshiharu Habu. It offers a sophisticated AI challenge and was the first game to showcase the N64''s processing power for strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush---extreme-racing-europe-enfrde', 'N64', 'San Francisco Rush - Extreme Racing (Europe) (En,Fr,De)', '1996', 'Racing', 'Midway', '2', 'Arcade Racing', 'Arcade-style racing with high jumps and hidden shortcuts.', 'Finish in first place while discovering secret keys and paths.', 'A classic arcade racing port set in the streets of San Francisco.', 'San Francisco Rush - Extreme Racing (Europe) brings the hit arcade experience to the N64. Master the hilly terrain of California, perform massive jumps, and find hidden shortcuts to beat your rivals in this high-octane racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush---extreme-racing-usa-enfrde', 'N64', 'San Francisco Rush - Extreme Racing (USA) (En,Fr,De)', '1996', 'Racing', 'Midway', '2', 'Arcade Racing', 'Arcade-style racing with high jumps and physics-based stunts.', 'Win the Grand Prix and unlock secret cars and tracks.', 'The North American release of the iconic street racing game.', 'San Francisco Rush - Extreme Racing (USA) is famous for its "Rush" physics. Explore realistic San Francisco landmarks, find all the hidden keys, and enjoy intense split-screen multiplayer on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush---extreme-racing-usa-enfrde-rev-a', 'N64', 'San Francisco Rush - Extreme Racing (USA) (En,Fr,De) (Rev A)', '1996', 'Racing', 'Midway', '2', 'Arcade Racing', 'Arcade-style racing with refined physics and bug fixes.', 'Master the tracks of San Francisco with improved game stability.', 'An updated revision of the North American arcade racing classic.', 'San Francisco Rush - Extreme Racing (USA) (Rev A) offers the most polished version of the original game. Experience smoother gameplay and corrected glitches as you fly through the streets of San Francisco.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush-2049-europe-enfrdeesitnl', 'N64', 'San Francisco Rush 2049 (Europe) (En,Fr,De,Es,It,Nl)', '1999', 'Racing', 'Midway', '4', 'Arcade Racing', 'Futuristic combat racing with flying mechanics and stunt wings.', 'Win the 2049 championship and master the stunt arenas.', 'A sci-fi racing sequel featuring flying cars and futuristic tracks.', 'San Francisco Rush 2049 (Europe) takes the franchise to the future. With high-speed combat racing and a dedicated stunt mode, it’s one of the most content-rich and visually impressive racers on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('san-francisco-rush-2049-usa', 'N64', 'San Francisco Rush 2049 (USA)', '1999', 'Racing', 'Midway', '4', 'Arcade Racing', 'Futuristic combat racing with high-speed aerial maneuvers.', 'Collect all coins and finish first in the futuristic metropolis.', 'The North American version of the high-speed sci-fi racer.', 'San Francisco Rush 2049 (USA) features incredible track designs and a deep customization system. Master the use of wings to stay airborne and dominate the 21st-century streets in this N64 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sand-birds-water-slide', 'N64', 'Sand Bird''s Water Slide', '2023', 'Platform', 'Independent', '1', 'Slide Challenge', 'Water-based slide platforming with momentum physics.', 'Navigate the shifting body of the Sand Bird to reach the end.', 'A custom Mario 64 level based on the famous Sunshine mission.', 'Sand Bird''s Water Slide is a creative mod that recreates the iconic Sand Bird challenge. Navigate a slippery, moving path high in the sky while mastering Mario''s water-slide physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sandy-spire-slide', 'N64', 'Sandy Spire Slide', '2023', 'Platform', 'Independent', '1', 'Slide Challenge', 'Fast-paced slide platforming in a desert-themed environment.', 'Reach the bottom of the spire without falling into the abyss.', 'A challenging custom slide level for the Super Mario 64 engine.', 'Sandy Spire Slide tests your reflexes and precision. Navigate a winding, steep path around a massive desert spire, collecting coins and avoiding obstacles in this high-speed N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sash-lilac-64', 'N64', 'Sash Lilac 64', '2023', 'Platform', 'Independent', '1', 'Indie Platformer', '3D platforming with high-speed movement and combat.', 'Complete levels using the acrobatic skills of Sash Lilac.', 'A character mod featuring Sash Lilac from Freedom Planet.', 'Sash Lilac 64 brings high-speed indie action to the N64. Play as the dragon girl with her signature hair-whip and dash attacks in this unique crossover modification for Super Mario 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('saturn-sonic-in-super-mario-64', 'N64', 'Saturn Sonic in Super Mario 64', '2023', 'Platform', 'Independent', '1', 'Character Mod', '3D platforming featuring the low-poly Saturn model of Sonic.', 'Navigate the Mushroom Kingdom as a retro-styled Sonic the Hedgehog.', 'A character swap mod featuring the Sega Saturn version of Sonic.', 'Saturn Sonic in Super Mario 64 is a nostalgic treat. Experience the classic N64 platformer with the aesthetic of a 32-bit rival, featuring custom animations and classic Sonic sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scary-piano-64', 'N64', 'Scary Piano 64', '2023', 'Horror', 'Independent', '1', 'Experimental Horror', 'Survival horror with a focus on a specific haunted object.', 'Survive the encounter with the possessed piano in the haunted house.', 'A spooky mod centered around the infamous piano from SM64.', 'Scary Piano 64 expands on one of Mario''s most famous scares. Navigate a haunted mansion where the environment itself is out to get you in this creepy and creative N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo!---classic-creep-capers-europe', 'N64', 'Scooby-Doo! - Classic Creep Capers (Europe)', '2000', 'Adventure', 'Software Creations', '1', 'Action Adventure', 'Point-and-click style adventure with puzzle solving and stealth.', 'Solve the mystery and unmask the villain without getting too scared.', 'A spooky adventure game based on the classic Scooby-Doo episodes.', 'Scooby-Doo! - Classic Creep Capers (Europe) captures the feel of the original cartoon. Help the gang find clues, build traps, and avoid monsters in this atmospheric N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo!---classic-creep-capers-usa', 'N64', 'Scooby-Doo! - Classic Creep Capers (USA)', '2000', 'Adventure', 'Software Creations', '1', 'Action Adventure', 'Point-and-click style adventure with puzzle solving and stealth.', 'Collect clues and solve three classic mysteries with Mystery Inc.', 'The North American release of the Scooby-Doo adventure game.', 'Scooby-Doo! - Classic Creep Capers (USA) lets you play as Shaggy and Scooby. Explore spooky locations like mansions and museums to solve cases in this faithful adaptation of the TV show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scooby-doo!---classic-creep-capers-usa-rev-a', 'N64', 'Scooby-Doo! - Classic Creep Capers (USA) (Rev A)', '2000', 'Adventure', 'Software Creations', '1', 'Action Adventure', 'Point-and-click style adventure with updated logic and fixes.', 'Complete the mysteries with improved game performance.', 'An updated revision of the North American Scooby-Doo game.', 'Scooby-Doo! - Classic Creep Capers (USA) (Rev A) provides a more stable experience for mystery solvers. Enjoy the classic cartoon atmosphere with refined puzzles and smoother gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scrooge-64', 'N64', 'Scrooge 64', '2023', 'Platform', 'Independent', '1', 'Fan Game', '3D platforming with a custom character model and coin focus.', 'Collect all the treasure in the castle as the world''s richest duck.', 'A character swap mod featuring Scrooge McDuck in SM64.', 'Scrooge 64 puts the legendary billionaire duck into the Mushroom Kingdom. Use his pogo-jump logic and custom model to explore levels and amass a fortune in this fun N64 hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scuttle-slide', 'N64', 'Scuttle Slide', '2023', 'Platform', 'Independent', '1', 'Slide Challenge', 'High-speed slide platforming with a focus on technical shortcuts.', 'Race to the finish line of the custom "Scuttle" themed slide.', 'A technical slide level designed for speedrunning enthusiasts.', 'Scuttle Slide is a mod built for fans of Mario 64''s sliding mechanics. Featuring tight turns and hidden time-saves, it’s a perfect challenge for players looking to master momentum and physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-hiryuu-no-ken-densetsu-japan', 'N64', 'SD Hiryuu no Ken Densetsu (Japan)', '1997', 'Fighting', 'Culture Brain', '2', 'Arcade Fighter', '2D/3D hybrid fighting game with traditional Japanese characters.', 'Defeat a series of mystical opponents to protect the kingdom.', 'A Japan-exclusive entry in the Flying Dragon fighting series.', 'SD Hiryuu no Ken Densetsu (Japan) features "Super Deformed" characters and deep combat mechanics. Master a variety of martial arts and special moves in this vibrant and fast-paced N64 brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seaside-village', 'N64', 'Seaside Village', '2023', 'Adventure', 'Independent', '1', 'Exploration Demo', '3D platforming in a tranquil, coastal custom environment.', 'Explore the village and collect hidden stars in the seaside area.', 'A peaceful and scenic custom level mod for Super Mario 64.', 'Seaside Village is a beautiful exploration-based mod. Wander through a sun-drenched coastal town, solving puzzles and discovering secrets in this relaxing addition to the N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-man-brazil', 'N64', 'Shadow Man (Brazil)', '1999', 'Action', 'Acclaim Studios Teesside', '1', 'Action Adventure', 'Third-person action-adventure with a dark, voodoo theme.', 'Protect the world of the living from the souls of Deadside.', 'A Brazilian localization of the dark action-horror title.', 'Shadow Man (Brazil) brings the epic voodoo journey to South American players. Explore the twisted landscapes of Deadside and collect Dark Souls to stop a group of serial killers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-man-europe-enesit', 'N64', 'Shadow Man (Europe) (En,Es,It)', '1999', 'Action', 'Acclaim Studios Teesside', '1', 'Action Adventure', 'Third-person action-adventure with a dark, voodoo theme.', 'Navigate between the worlds of the Living and the Dead.', 'The multi-language European release of the voodoo action game.', 'Shadow Man (Europe) is a deep, atmospheric adventure inspired by the Valiant comic. Use voodoo powers and high-tech weaponry to stop an impending apocalypse in this dark N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-man-france', 'N64', 'Shadow Man (France)', '1999', 'Action', 'Acclaim Studios Teesside', '1', 'Action Adventure', 'Third-person action-adventure with French localization.', 'Stop the Legion of serial killers and preserve the balance of souls.', 'The localized French version of the Shadow Man adventure.', 'Shadow Man (France) offers the full, dark narrative of Michael LeRoi in French. Experience the haunting atmosphere and complex exploration of Deadside on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-man-germany', 'N64', 'Shadow Man (Germany)', '1999', 'Action', 'Acclaim Studios Teesside', '1', 'Action Adventure', 'Third-person action-adventure with German localization.', 'Prevent the end of the world by conquering the Deadside.', 'The localized German version of the dark action-horror game.', 'Shadow Man (Germany) brings the gritty, mature story of the Shadow Man to German fans. Explore vast, non-linear levels and master supernatural abilities to defeat evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-man-usa', 'N64', 'Shadow Man (USA)', '1999', 'Action', 'Acclaim Studios Teesside', '1', 'Action Adventure', 'Third-person action-adventure with a dark, voodoo theme.', 'Journey through Deadside to stop the coming of the Dark Souls.', 'The North American release of the acclaimed voodoo horror game.', 'Shadow Man (USA) is one of the N64''s most mature and ambitious titles. With a huge world to explore and a haunting soundtrack, it offers a deep adventure that blends action, platforming, and horror.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowgate-64---trials-of-the-four-towers-europe', 'N64', 'Shadowgate 64 - Trials of the Four Towers (Europe)', '1999', 'Adventure', 'Zojoi / TNS', '1', 'First-Person Adventure', 'First-person adventure and puzzle-solving in a fantasy setting.', 'Navigate the Four Towers to uncover the secrets of Shadowgate.', 'A 3D sequel to the classic point-and-click adventure game.', 'Shadowgate 64 - Trials of the Four Towers (Europe) is an atmospheric journey. Solve complex puzzles and avoid deadly traps in this dark fantasy world, presented with immersive first-person graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowgate-64---trials-of-the-four-towers-europe-esit', 'N64', 'Shadowgate 64 - Trials of the Four Towers (Europe) (Es,It)', '1999', 'Adventure', 'Zojoi / TNS', '1', 'First-Person Adventure', 'First-person adventure with Spanish and Italian localization.', 'Solve the riddles of the towers to restore the kingdom.', 'A European version of Shadowgate 64 with South-European languages.', 'Shadowgate 64 (Europe) (Es,It) allows Spanish and Italian players to experience the deep lore and challenging puzzles of the Shadowgate universe in their native languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowgate-64---trials-of-the-four-towers-europe-frdenl', 'N64', 'Shadowgate 64 - Trials of the Four Towers (Europe) (Fr,De,Nl)', '1999', 'Adventure', 'Zojoi / TNS', '1', 'First-Person Adventure', 'First-person adventure with French, German, and Dutch localization.', 'Survive the trials and uncover the truth behind the shadows.', 'A Northern European multi-language release of Shadowgate 64.', 'Shadowgate 64 (Europe) (Fr,De,Nl) brings the legendary trial of the Four Towers to a wider audience. Explore the beautifully rendered ruins and solve intricate puzzles to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowgate-64---trials-of-the-four-towers-japan', 'N64', 'Shadowgate 64 - Trials of the Four Towers (Japan)', '1999', 'Adventure', 'Zojoi / TNS', '1', 'First-Person Adventure', 'First-person adventure and puzzle-solving in a fantasy setting.', 'Overcome the deadly trials within the ancient fortress.', 'The Japanese version of the atmospheric fantasy adventure.', 'Shadowgate 64 - Trials of the Four Towers (Japan) delivers a haunting and cerebral experience. With its focus on storytelling and logic-based puzzles, it is a unique title in the N64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadowgate-64---trials-of-the-four-towers-usa-enes', 'N64', 'Shadowgate 64 - Trials of the Four Towers (USA) (En,Es)', '1999', 'Adventure', 'Zojoi / TNS', '1', 'First-Person Adventure', 'First-person adventure with English and Spanish localization.', 'Explore the depths of Shadowgate and survive its many dangers.', 'The North American version featuring English and Spanish text.', 'Shadowgate 64 - Trials of the Four Towers (USA) is a must-play for fans of fantasy and puzzles. Immerse yourself in the dark history of the castle and use your wits to survive the Trial.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shifting-sand-dungeon', 'N64', 'Shifting Sand Dungeon', '2023', 'Adventure', 'Independent', '1', 'Dungeon Mod', '3D platforming in a treacherous, sand-filled custom dungeon.', 'Navigate the desert ruins to find the hidden power star.', 'A custom-built dungeon level for Super Mario 64.', 'Shifting Sand Dungeon is a challenging mod that emphasizes platforming and hazard avoidance. Explore the ancient, shifting sands of this custom dungeon to uncover its many secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wrestling-toukon-road---brave-spirits-japan', 'N64', 'Shin Nihon Pro Wrestling Toukon Road - Brave Spirits (Japan)', '1997', 'Sports', 'Yuke’s', '2', 'Pro Wrestling', 'Professional wrestling simulation with realistic physics and rosters.', 'Win the championship belt in the New Japan Pro Wrestling league.', 'A realistic wrestling game featuring NJPW stars and mechanics.', 'Shin Nihon Pro Wrestling Toukon Road (Japan) offers an authentic look at Japanese wrestling. Master the grapple system and experience the intensity of the ring with a roster of legendary fighters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shin-nihon-pro-wrestling-toukon-road-2---the-next-generation-japan', 'N64', 'Shin Nihon Pro Wrestling Toukon Road 2 - The Next Generation (Japan)', '1999', 'Sports', 'Yuke’s', '2', 'Pro Wrestling', 'Professional wrestling simulation with expanded rosters and modes.', 'Rise to the top of the next generation of Japanese wrestling.', 'The sequel to the acclaimed NJPW wrestling simulation.', 'Shin Nihon Pro Wrestling Toukon Road 2 (Japan) improves on its predecessor with better graphics and more technical moves. It remains a fan favorite for its realistic approach to pro wrestling on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-stars-4-:-elephant-star-adventure', 'N64', 'Shining Stars 4 : Elephant Star Adventure', '2023', 'Platform', 'Independent', '1', 'Adventure Platformer', '3D platforming with a focus on custom characters and elephant-themed mechanics.', 'Collect the Elephant Star by completing a series of creative jungle trials.', 'A vibrant Super Mario 64 mod featuring custom assets and a unique story.', 'Shining Stars 4: Elephant Star Adventure is a colorful expansion of the Mario 64 engine. Explore new worlds, interact with custom NPCs, and master new movement styles in this imaginative N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shotgun-mario-64', 'N64', 'Shotgun Mario 64', '2023', 'Action', 'Independent', '1', 'Action Mod', 'Third-person action-platformer featuring a shotgun weapon mechanic.', 'Blast through enemies and obstacles to reach the Power Stars.', 'A high-octane mod that gives Mario a powerful shotgun to use.', 'Shotgun Mario 64 changes the pace of the Mushroom Kingdom. Instead of jumping on heads, use firepower to clear levels and solve puzzles in this fast-paced and humorous N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silver-the-hedgehog-64-night', 'N64', 'Silver The Hedgehog 64 NIGHT', '2023', 'Platform', 'Independent', '1', 'Character Mod', 'High-speed 3D platforming featuring Silver the Hedgehog.', 'Navigate futuristic and dark environments using psychokinetic powers.', 'A character-swap mod bringing Silver from Sonic the Hedgehog to N64.', 'Silver The Hedgehog 64 NIGHT offers a dark, high-speed experience. Utilize Silver’s custom model and abilities to glide through redesigned levels inspired by the Sonic series on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silverexe-64', 'N64', 'Silver.exe 64', '2023', 'Horror', 'Independent', '1', 'Creepypasta Horror', 'Horror-themed 3D platforming with glitch aesthetics and scares.', 'Escape the digital nightmare created by the corrupted Silver.exe.', 'A "Creepypasta" inspired horror mod for the Mario 64 engine.', 'Silver.exe 64 is a psychological horror experience for the N64. Explore distorted levels, avoid terrifying entities, and uncover the mystery of this corrupted game world in a unique fan-made project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simcity-2000-japan', 'N64', 'SimCity 2000 (Japan)', '1996', 'Simulation', 'Maxis', '1', 'City Simulation', 'City-building simulation with deep economic and management layers.', 'Build and manage a thriving metropolis while surviving disasters.', 'The Japanese console port of the legendary city-building simulator.', 'SimCity 2000 (Japan) brings the classic PC strategy game to the N64. Manage taxes, zoning, and infrastructure to grow your city from a small village to a massive futuristic megalopolis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpleflipss-mansion', 'N64', 'SimpleFlips''s Mansion', '2023', 'Platform', 'Independent', '1', 'Exploration Platformer', '3D platforming and exploration within a custom-built mansion hub.', 'Find hidden secrets and stars throughout the streamer-inspired mansion.', 'A custom level mod dedicated to the personality SimpleFlips.', 'SimpleFlips''s Mansion is a community-driven mod for Super Mario 64. Explore a vast, intricately designed mansion filled with memes, inside jokes, and challenging platforming secrets for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sin-and-punishment---successor-of-the-earth-english-translation', 'N64', 'Sin and Punishment - Successor of the Earth (English Translation)', '2000', 'Action', 'Treasure', '1', 'Run and Gun', 'Rail-shooter with intense combat and fast-paced movement.', 'Destroy the biological threat and save humanity in a dystopian future.', 'A fan-translated version of the legendary Treasure-developed shooter.', 'Sin and Punishment (English Translation) allows western players to finally understand the deep story of this N64 masterpiece. Experience high-speed action and cinematic battles in this definitive rail-shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ski-in-super-mario-64', 'N64', 'Ski in Super Mario 64', '2023', 'Platform', 'Independent', '1', 'Skill Challenge', '3D sports simulation using the Mario 64 engine.', 'Master the slopes and finish the downhill race in record time.', 'A specialized mod that replaces Mario''s movement with skiing.', 'Ski in Super Mario 64 transforms the platformer into a winter sports game. Navigate snowy peaks, perform tricks, and manage your momentum on skis in this creative technical modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slippy-toad-for-smash-remix-10', 'N64', 'Slippy Toad for Smash Remix 1.0', '2023', 'Fighting', 'Independent', '4', 'Character Mod', '2.5D crossover fighting with an expanded roster and move sets.', 'Win the Smash tournament using Slippy''s technical gadgets and moves.', 'A character mod for Smash Remix that adds the Star Fox pilot.', 'Slippy Toad for Smash Remix 1.0 brings the legendary pilot to the fight. Utilize his unique projectiles and nimble movements to dominate the competition in this massive N64 expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-astroslide', 'N64', 'SM64 Astroslide', '2023', 'Platform', 'Independent', '1', 'Slide Challenge', 'High-speed slide platforming set in a cosmic, star-filled environment.', 'Reach the end of the stellar slide without falling into the void.', 'A space-themed technical slide mod for Super Mario 64.', 'SM64 Astroslide focuses on precision and high-speed maneuvers. Navigate a futuristic slide through the stars, mastering the physics and momentum of the N64''s most famous platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-castle-remix', 'N64', 'SM64 Castle Remix', '2023', 'Platform', 'Independent', '1', 'Level Remix', '3D platforming with a total overhaul of the Peach''s Castle hub.', 'Explore a completely redesigned castle to find new hidden paths.', 'A creative mod that remixes the central hub of Super Mario 64.', 'SM64 Castle Remix offers a fresh perspective on a familiar location. Discover new rooms, secret shortcuts, and updated textures within the iconic Peach''s Castle in this N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-christmas-hack', 'N64', 'SM64 Christmas Hack', '2023', 'Platform', 'Independent', '1', 'Seasonal Event', 'Festive 3D platforming with holiday decorations and winter themes.', 'Help Mario save Christmas by collecting stars in a snowy world.', 'A heartwarming holiday-themed hack for Super Mario 64.', 'SM64 Christmas Hack brings the holiday spirit to the N64. Explore levels covered in snow, decorated with lights, and featuring custom festive music in this cozy seasonal adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-christmas-land', 'N64', 'SM64 Christmas Land', '2023', 'Platform', 'Independent', '1', 'Seasonal Event', '3D platforming in a winter wonderland with custom mechanics.', 'Navigate the Christmas Land to find all the hidden holiday treats.', 'A large-scale winter mod with unique levels and winter assets.', 'SM64 Christmas Land is an expansive holiday project. Experience entire new worlds built around Christmas themes, featuring high-quality textures and creative platforming challenges for retro gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-green-demon-challenge-ingoh-version', 'N64', 'SM64 Green Demon Challenge (IngoH Version)', '2023', 'Platform', 'Independent', '1', 'Challenge Run', 'Survival-style 3D platforming with a persistent chasing enemy.', 'Collect the 1-Up mushroom and reach the star before the demon catches you.', 'A challenging "Green Demon" chase mod for Super Mario 64.', 'SM64 Green Demon Challenge (IngoH Version) tests your speed and planning. Avoid the relentless Green Demon mushroom that follows your every move in this high-tension N64 gameplay mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-legend-of-peach', 'N64', 'SM64 Legend of Peach', '2023', 'Platform', 'Independent', '1', 'Story Mod', '3D action-adventure following the journey of Princess Peach.', 'Rescue Mario and the kingdom using Peach''s unique abilities.', 'A total conversion mod that puts Princess Peach in the lead role.', 'SM64 Legend of Peach reimagines the N64 classic. Play as Peach with custom animations and floating mechanics to conquer new levels and save Mario in this impressive fan-made sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-scaling-test', 'N64', 'SM64 Scaling Test', '2023', 'Platform', 'Independent', '1', 'Technical Test', 'Technical demonstration of object and character scaling.', 'Observe how the game world reacts to dynamic size changes.', 'A technical mod designed to test the limits of the SM64 engine.', 'SM64 Scaling Test is a fascinating look behind the scenes of N64 modding. Experiment with Mario''s size and environmental scale to see how it affects physics and gameplay mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-slide', 'N64', 'SM64 Slide', '2023', 'Platform', 'Independent', '1', 'Slide Challenge', 'Fast-paced slide platforming focused on time-trial challenges.', 'Race against the clock to master a series of complex slides.', 'A compilation of high-speed slides for the Mario 64 engine.', 'SM64 Slide is a dream for fans of the game''s racing mechanics. Focus purely on the joy of sliding with a variety of custom-built tracks designed to test your reflexes and speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64-x-cuphead-demo', 'N64', 'SM64 x Cuphead DEMO', '2023', 'Action', 'Independent', '1', 'Crossover Demo', '2D/3D hybrid platformer with a hand-drawn 1930s aesthetic.', 'Defeat bosses and clear levels in the style of Cuphead.', 'A unique crossover demo bringing Cuphead''s style to the N64.', 'SM64 x Cuphead DEMO is a visual marvel. Experience the challenging "run and gun" gameplay of Cuphead within the 3D space of the Nintendo 64, featuring custom assets and animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64:-beyond-the-cursed-mirror-13', 'N64', 'SM64: Beyond the Cursed Mirror 1.3', '2023', 'Platform', 'Independent', '1', 'Horror Adventure', '3D platforming in a dark, twisted version of the Mushroom Kingdom.', 'Enter the cursed mirror to fix a fractured and dangerous reality.', 'A large-scale rom hack with a mature atmosphere and new levels.', 'SM64: Beyond the Cursed Mirror 1.3 offers a deep and mysterious adventure. Explore a parallel world with unique challenges, custom music, and a compelling new narrative for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64:-the-parallel-universes', 'N64', 'SM64: The Parallel Universes', '2023', 'Platform', 'Independent', '1', 'Total Conversion', '3D platforming across multiple shifting dimensions.', 'Navigate through parallel versions of levels to collect stars.', 'A complex mod that utilizes the "parallel universes" game logic.', 'SM64: The Parallel Universes is a mind-bending platformer. Use unique mechanics to jump between different versions of the same level, solving puzzles and finding hidden paths on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sm64z64', 'N64', 'sm64.z64', '1996', 'Platform', 'Nintendo', '1', 'Base Game Dump', '3D platforming in the original, untouched classic world.', 'Collect all 120 stars and defeat Bowser to rescue Princess Peach.', 'The original source file/ROM of the legendary Super Mario 64.', 'sm64.z64 is the foundation of 3D gaming. Experience the masterpiece that defined the genre, featuring tight controls, iconic levels, and the timeless charm of the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-64-skin-modpack', 'N64', 'Smash 64 (Skin Modpack)', '2023', 'Fighting', 'Independent', '4', 'Skin Pack', '2.5D crossover fighting with custom character skins and visuals.', 'Battle your favorite Nintendo characters with a fresh new look.', 'A visual modpack that updates the textures and skins of Smash 64.', 'Smash 64 (Skin Modpack) gives the original roster a modern or thematic makeover. Enjoy the classic fighting gameplay with updated character models and vibrant new arena textures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-&-knuckles-b23', 'N64', 'Smash Remix & Knuckles b2.3', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting featuring Knuckles and new mechanics.', 'Master Knuckles'' gliding and climbing in a competitive setting.', 'An expansion of Smash Remix that highlights Knuckles the Echidna.', 'Smash Remix & Knuckles b2.3 adds the iconic Sonic character to the N64 roster. Experience refined combat and brand-new stages in this high-quality community expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-094', 'N64', 'Smash Remix 0.9.4', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with an expanded roster and stages.', 'Defeat the original and new characters in updated arenas.', 'An early version of the massive Smash 64 expansion project.', 'Smash Remix 0.9.4 introduced the first major wave of new content to the original Smash Bros. Experience new characters and technical fixes that began the "Remix" revolution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-095b', 'N64', 'Smash Remix 0.9.5b', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with technical balance and new fighters.', 'Win the tournament using a more balanced and diverse roster.', 'A refined update to the Smash Remix series with character tweaks.', 'Smash Remix 0.9.5b focused on balancing the competitive gameplay. With subtle adjustments to the expanded roster, it offers a more professional feel to the N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-097', 'N64', 'Smash Remix 0.9.7', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with additional modes and characters.', 'Explore new ways to play Smash with an ever-growing roster.', 'A significant update in the Smash Remix development cycle.', 'Smash Remix 0.9.7 continued to push the limits of the N64. With more stages and legendary characters added, it remains a favorite for fans of the "mid-era" Remix project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-101', 'N64', 'Smash Remix 1.0.1', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with major performance and content updates.', 'Experience the most complete version of Smash 64 to date.', 'A milestone version of the Smash Remix project with high stability.', 'Smash Remix 1.0.1 represents a massive leap in quality. Featuring a huge roster of characters like Falco and Ganondorf, it transforms the original game into a modern fighting experience.');
