INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-111', 'N64', 'Smash Remix 1.1.1', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with bug fixes and roster refinements.', 'Compete in the ultimate Nintendo crossover with optimized gameplay.', 'A stability-focused update for the 1.1 series of Smash Remix.', 'Smash Remix 1.1.1 ensures a smooth experience for competitive and casual players alike. Enjoy the massive character selection with fewer bugs and better performance on original hardware.');
