INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-121', 'N64', 'Smash Remix 1.2.1', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with minor technical adjustments.', 'Defeat opponents using an expanded roster of classic Nintendo icons.', 'A maintenance update for the Smash Remix series with bug fixes.', 'Smash Remix 1.2.1 provides essential stability improvements to the massive N64 mod. Enjoy seamless combat with a huge roster of characters, now with refined performance and fewer glitches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-122', 'N64', 'Smash Remix 1.2.2', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with refined move sets and balance.', 'Master the unique abilities of new and classic fighters.', 'An incremental update to the Smash Remix project for better balance.', 'Smash Remix 1.2.2 focuses on competitive integrity. This version tweaks character frame data and move properties to ensure a fair and exciting fighting experience on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-130', 'N64', 'Smash Remix 1.3.0', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting featuring new legendary characters.', 'Rise to the top of the ranks in the ultimate N64 crossover.', 'A major content update adding new fighters and stages to the roster.', 'Smash Remix 1.3.0 expands the N64 fighting world even further. With new fan-favorite characters and custom-built arenas, it pushes the boundaries of what is possible on original hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-131', 'N64', 'Smash Remix 1.3.1', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with optimized performance and logic.', 'Win the Smash tournament in the most stable 1.3 build.', 'A polished version of the 1.3 update with various game fixes.', 'Smash Remix 1.3.1 ensures a smooth gameplay experience for up to four players. This update addresses community feedback to provide a more reliable and polished N64 brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-140', 'N64', 'Smash Remix 1.4.0', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with advanced game modes and assets.', 'Explore new ways to play Smash with massive roster additions.', 'A significant leap in content featuring new character models and modes.', 'Smash Remix 1.4.0 introduces groundbreaking features to the classic N64 fighter. Experience new gameplay mechanics and a wider selection of legendary Nintendo and Sega characters.');
