INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-150', 'N64', 'Smash Remix 1.5.0', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with a huge expansion of the roster.', 'Master the newly added fighters in high-speed combat.', 'A massive content drop that adds several new characters to the game.', 'Smash Remix 1.5.0 is a tribute to gaming history. This version adds even more iconic fighters, each with unique move sets and animations, transforming the N64 original into a modern giant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-151', 'N64', 'Smash Remix 1.5.1', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with gameplay balance and bug fixes.', 'Compete in the most balanced version of the 1.5 series.', 'A refined update focused on competitive play and bug squashing.', 'Smash Remix 1.5.1 addresses minor issues from the previous version, ensuring that the huge roster remains balanced and fun for both casual and professional N64 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-152', 'N64', 'Smash Remix 1.5.2', '2023', 'Fighting', 'Independent', '4', 'Expansion Mod', '2.5D crossover fighting with final 1.5 series polish.', 'Experience the peak of the 1.5 era with optimized performance.', 'The most stable and complete version of the Smash Remix 1.5 series.', 'Smash Remix 1.5.2 is the definitive build for this era of the project. It features all the characters and stages of 1.5 with the highest level of technical polish available for N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-200', 'N64', 'Smash Remix 2.0.0', '2023', 'Fighting', 'Independent', '4', 'Major Expansion', '2.5D crossover fighting with a revolutionary new UI and roster.', 'Discover the ultimate Smash experience with the biggest update yet.', 'A total overhaul of the game with a massive 2.0.0 roster and features.', 'Smash Remix 2.0.0 is a technical masterpiece. Featuring a professional-grade UI, dozens of characters, and incredible new stages, it is the most advanced fighting game on the Nintendo 64.');
