INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smash-remix-sonic-in-mario-64', 'N64', 'Smash Remix Sonic in Mario 64', '2023', 'Fighting', 'Independent', '4', 'Crossover Mod', '3D platforming crossover featuring Sonic the Hedgehog.', 'Navigate the Mushroom Kingdom at supersonic speeds as Sonic.', 'A character-swap mod that puts Sonic into the Super Mario 64 engine.', 'Smash Remix Sonic in Mario 64 is a dream crossover. Use Sonic''s speed and custom animations to collect stars and explore Peach''s castle in this high-speed N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smashma-halloween', 'N64', 'Smashma Halloween', '2023', 'Fighting', 'Independent', '4', 'Seasonal Event', '2.5D crossover fighting with a spooky Halloween theme.', 'Defeat creepy-themed versions of characters in haunted arenas.', 'A seasonal modification of Smash 64 featuring Halloween assets.', 'Smashma Halloween brings a spooky vibe to the arena. Fight as costumed characters on haunted stages with custom textures and music for a unique N64 holiday experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smg:-star-shell-adventure-v10', 'N64', 'SMG: Star Shell Adventure v1.0', '2023', 'Platform', 'Independent', '1', 'Indie Platformer', '3D platforming with a focus on star shell projectiles and movement.', 'Complete custom levels using the star shell mechanic from SMG.', 'A Mario 64 mod that replicates Super Mario Galaxy''s shell gameplay.', 'SMG: Star Shell Adventure v1.0 brings modern mechanics to the N64. Master the art of surfing and attacking with star shells through beautifully designed custom levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smg4:-the-1337-police-mod!', 'N64', 'SMG4: The 1337 police mod!', '2023', 'Action', 'Independent', '1', 'Comedy Mod', '3D action-comedy game featuring custom voice lines and humor.', 'Complete hilarious missions as the 1337 police force.', 'A humor-focused mod based on the SMG4 internet series.', 'SMG4: The 1337 police mod! is a wild and funny adventure. Explore a meme-filled world with custom dialogue, wacky scenarios, and unique characters from the popular YouTube series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snobo-kids-japan', 'N64', 'Snobo Kids (Japan)', '1998', 'Sports', 'Racdym', '4', 'Snowboarding', 'Snowboard racing with a distinct "chibi" anime art style.', 'Win races and use wacky items to defeat your opponents.', 'The original Japanese release of the beloved Snowboard Kids.', 'Snobo Kids (Japan) features unique characters and fast-paced downhill racing. Use fans, bombs, and pans to sabotage your rivals in this charming N64 racing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snow-speeder-japan', 'N64', 'Snow Speeder (Japan)', '1997', 'Action', 'Nintendo', '1', 'Arcade Shooter', 'High-speed futuristic racing on snowy mountain tracks.', 'Master the snow speeder''s physics to win the tournament.', 'A Japan-exclusive racing game featuring specialized snow vehicles.', 'Snow Speeder (Japan) offers a unique take on winter sports. Navigate icy tracks with futuristic craft, focusing on speed and technical maneuvering across a variety of scenic mountain levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snowboard-kids-europe', 'N64', 'Snowboard Kids (Europe)', '1998', 'Sports', 'Racdym', '4', 'Snowboarding', 'Snowboard racing with items, tricks, and character progression.', 'Climb the ranks of the Snowboard Kids championship circuit.', 'The European release of the iconic arcade-style snowboard racer.', 'Snowboard Kids (Europe) is a multiplayer favorite. Combine high-speed racing with creative combat items and a rewarding trick system to earn gold and upgrade your gear on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snowboard-kids-usa', 'N64', 'Snowboard Kids (USA)', '1998', 'Sports', 'Racdym', '4', 'Snowboarding', 'Snowboard racing with items, tricks, and character progression.', 'Become the ultimate Snowboard Kid by winning every race.', 'The North American version of the cult classic snowboard game.', 'Snowboard Kids (USA) features a vibrant soundtrack and tight controls. Master the art of the 360 spin and the board-grab to earn money for better boards and power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snowboard-kids-2-australia', 'N64', 'Snowboard Kids 2 (Australia)', '1999', 'Sports', 'Racdym', '4', 'Snowboarding', 'Snowboard racing with an expanded roster and adventure mode.', 'Save the world of snowboarding and win the world tour.', 'The rare Australian PAL release of the acclaimed snowboard sequel.', 'Snowboard Kids 2 (Australia) brings even more fun to the slopes. With new characters like Damien and Wendy, and a full story mode, it is one of the most sought-after racing titles on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snowboard-kids-2-usa', 'N64', 'Snowboard Kids 2 (USA)', '1999', 'Sports', 'Racdym', '4', 'Snowboarding', 'Snowboard racing with an expanded roster and adventure mode.', 'Win the various cups and complete the story-driven challenges.', 'The North American release of the feature-rich snowboard sequel.', 'Snowboard Kids 2 (USA) improves every aspect of the original. Explore diverse locations from tropical islands to space, all while enjoying the signature item-based combat and racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snowy-wonderland', 'N64', 'Snowy Wonderland', '2023', 'Platform', 'Independent', '1', 'Seasonal Event', '3D platforming in a serene and magical winter landscape.', 'Explore the frozen world and collect hidden holiday stars.', 'A peaceful and visually stunning winter mod for Super Mario 64.', 'Snowy Wonderland is a beautiful exploration-based hack. Wander through sparkling snow and icy caves, solving environmental puzzles in this relaxing and atmospheric N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('somari-64-sonic', 'N64', 'Somari 64 Sonic', '2023', 'Platform', 'Independent', '1', 'Character Mod', '3D platforming with a custom "Somari" character model.', 'Explore the Mushroom Kingdom as the legendary Somari bootleg character.', 'A humorous mod based on the famous Mario/Sonic bootleg fusion.', 'Somari 64 Sonic brings an internet gaming icon to the N64. Play as the quirky hybrid character "Somari" in a fully 3D world, featuring custom movement and retro-inspired textures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('somari-64:-dash!', 'N64', 'Somari 64: DASH!', '2023', 'Platform', 'Independent', '1', 'Character Mod', 'High-speed 3D platforming focused on dashing mechanics.', 'Complete technical platforming challenges using a dash ability.', 'A speed-focused mod for the Somari/Sonic crossover series.', 'Somari 64: DASH! emphasizes momentum and quick reflexes. Navigate complex custom levels designed to test your mastery of the dash mechanic in this high-energy N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-adventure-64', 'N64', 'Sonic Adventure 64', '2023', 'Platform', 'Independent', '1', 'Fan Adventure', '3D platforming inspired by the gameplay of Sonic Adventure.', 'Explore open zones and collect rings as Sonic the Hedgehog.', 'A technical mod that attempts to bring the Sonic Adventure feel to N64.', 'Sonic Adventure 64 is a fascinating experiment in N64 modding. Experience Sonic-style physics, custom sound effects, and open level designs that pay homage to the Dreamcast classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-in-marios-mind-11', 'N64', 'Sonic in Mario''s Mind 1.1', '2023', 'Platform', 'Independent', '1', 'Psychological Mod', 'Surreal 3D platforming within a psychological dream world.', 'Navigate the bizarre landscapes of Mario''s subconscious as Sonic.', 'A creative and abstract mod featuring Sonic in Mario 64.', 'Sonic in Mario''s Mind 1.1 offers a unique narrative experience. Explore distorted versions of classic levels and solve surreal puzzles in this atmospheric and artistic N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-in-ocarina-of-time', 'N64', 'Sonic in Ocarina of Time', '2023', 'Adventure', 'Independent', '1', 'Character Mod', '3D action-adventure with a protagonist model swap.', 'Save Hyrule using the speed and style of Sonic the Hedgehog.', 'A character-swap mod for Ocarina of Time featuring Sonic.', 'Sonic in Ocarina of Time is the ultimate retro crossover. Run through the fields of Hyrule at high speed and take on Ganondorf as the Blue Blur in this fun and functional N64 mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-werehog-64', 'N64', 'Sonic The Werehog 64', '2023', 'Action', 'Independent', '1', 'Action Platformer', '3D platforming with a combat-focused "Werehog" mechanic.', 'Battle enemies and climb through levels using powerful beastly arms.', 'A mod based on the Sonic Unleashed Werehog gameplay style.', 'Sonic The Werehog 64 brings a dark twist to the engine. Focus on melee combat and unique stretching-arm platforming in this creative interpretation of Sonic’s beastly form for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-wings-assault-japan', 'N64', 'Sonic Wings Assault (Japan)', '1997', 'Action', 'Video System', '2', 'Vertical Shooter', 'High-speed aerial combat with a variety of fighter jets.', 'Shoot down enemy forces and complete dangerous flight missions.', 'The Japanese version of the intense shooter Aero Fighters Assault.', 'Sonic Wings Assault (Japan) offers explosive aerial action. Choose from several pilots and aircraft to engage in high-stakes dogfights and massive boss battles across global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-world-64---first', 'N64', 'Sonic World 64 - First', '2023', 'Platform', 'Independent', '1', 'Open World Platformer', '3D platforming in custom levels inspired by Sonic''s world.', 'Race to the goal and collect emeralds in a 64-bit Sonic world.', 'The first entry in a series of custom Sonic-themed N64 mods.', 'Sonic World 64 - First is a nostalgic project that brings Green Hill vibes to the N64. Explore custom levels built for speed and enjoy a unique take on the classic Sonic formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-world-64---hard-mode-beta1', 'N64', 'Sonic World 64 - Hard Mode BETA1', '2023', 'Platform', 'Independent', '1', 'Challenge Mode', 'High-difficulty 3D platforming for experienced players.', 'Survive extreme platforming trials in a high-speed Sonic environment.', 'A challenging "hard mode" beta for the Sonic World 64 project.', 'Sonic World 64 - Hard Mode BETA1 is designed for speedrunning and precision. Test your skills against difficult enemy placement and tight jumps in this intense N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-world-64-original', 'N64', 'Sonic World 64 (Original)', '2023', 'Platform', 'Independent', '1', 'Open World Platformer', '3D platforming with original custom assets and Sonic physics.', 'Complete the classic adventure as the world''s fastest hedgehog.', 'The initial release of the comprehensive Sonic World 64 project.', 'Sonic World 64 (Original) set the standard for Sonic hacks on the N64. Experience custom-built zones, classic Sonic sound effects, and high-speed platforming in this landmark fan-made title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sooper-wooper-64', 'N64', 'Sooper Wooper 64', '2023', 'Platform', 'Independent', '1', 'Indie Platformer', 'High-speed 3D platforming with custom gravity and physics.', 'Reach the end of surreal levels using specialized movement logic.', 'A creative technical mod for the Super Mario 64 engine.', 'Sooper Wooper 64 is a unique N64 mod that experiments with physics and environmental interactions. Navigate through abstract levels and master new movement mechanics in this innovative fan-made project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sora-mario', 'N64', 'Sora Mario', '2023', 'Platform', 'Independent', '1', 'Character Mod', '3D action-platforming featuring Kingdom Hearts aesthetic.', 'Explore the Mushroom Kingdom using Sora''s iconic Keyblade.', 'A character swap mod that brings Sora into the world of SM64.', 'Sora Mario combines the magic of Kingdom Hearts with the platforming of the N64. Play as Sora with custom models and animations, bringing a touch of Square Enix style to the classic Mario engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park---chefs-luv-shack-europe', 'N64', 'South Park - Chef''s Luv Shack (Europe)', '1998', 'Party', 'Acclaim', '4', 'Multiplayer Party', '2D trivia and party game featuring crude humor and minigames.', 'Win the quiz show by answering questions and winning minigames.', 'A South Park themed party game hosted by the character Chef.', 'South Park - Chef''s Luv Shack (Europe) brings the show''s irreverent humor to the N64. Compete with friends in wacky trivia rounds and diverse minigames in this multi-player party classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park---chefs-luv-shack-usa', 'N64', 'South Park - Chef''s Luv Shack (USA)', '1998', 'Party', 'Acclaim', '4', 'Multiplayer Party', '2D trivia and party game featuring crude humor and minigames.', 'Outsmart your friends to become the ultimate quiz champion.', 'The North American version of the South Park trivia party game.', 'South Park - Chef''s Luv Shack (USA) features original voice acting from the show''s cast. Perfect for fans, it offers a variety of hilarious and often mature minigames for up to four players on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-brazil', 'N64', 'South Park (Brazil)', '1998', 'Action', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with a focus on projectile-based combat.', 'Save South Park from an onslaught of turkeys and aliens.', 'The Brazilian localization of the first South Park FPS.', 'South Park (Brazil) brings the iconic town to life for South American players. Use wacky weapons like the cow launcher to defend the town in this humorous and chaotic 3D shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-europe-enfres', 'N64', 'South Park (Europe) (En,Fr,Es)', '1998', 'Action', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with a focus on projectile-based combat.', 'Protect the town from various bizarre threats in story mode.', 'The multi-language European release of the South Park FPS.', 'South Park (Europe) features the classic Turok-engine gameplay. Battle through snowy environments and defend the town using a variety of unconventional gadgets and weapons from the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-germany', 'N64', 'South Park (Germany)', '1998', 'Action', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with German localization.', 'Neutralize the threats invading the quiet mountain town.', 'The localized German version of the South Park shooter.', 'South Park (Germany) allows German fans to experience the show''s transition to 3D. Fight against giant turkeys and clones while enjoying the signature art style of the early seasons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-usa', 'N64', 'South Park (USA)', '1998', 'Action', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with a focus on projectile-based combat.', 'Stop the various evils threatening the town of South Park.', 'The definitive North American release of the first South Park game.', 'South Park (USA) is a fast-paced FPS filled with humor and iconic locations. Explore the town in 3D, collect power-ups, and engage in hilarious multiplayer battles with up to four players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-rally-europe', 'N64', 'South Park Rally (Europe)', '1999', 'Racing', 'Acclaim', '4', 'Arcade Racing', 'Arcade kart racing with items and objective-based modes.', 'Win races and complete varied missions across South Park.', 'A chaotic racing game featuring characters and cars from the show.', 'South Park Rally (Europe) adds a twist to the kart racing genre. Instead of just laps, players must complete specific objectives across various maps based on classic episodes of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('south-park-rally-usa', 'N64', 'South Park Rally (USA)', '1999', 'Racing', 'Acclaim', '4', 'Arcade Racing', 'Arcade kart racing with items and objective-based modes.', 'Unlock all characters and become the king of the rally.', 'The North American version of the item-based South Park racer.', 'South Park Rally (USA) features over 20 playable characters and a wide range of creative weapons. Navigate the town''s streets and survive the madness in this high-energy N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-dynamites-japan', 'N64', 'Space Dynamites (Japan)', '1996', 'Shooter', 'Taito', '2', 'Arcade Shooter', '3D arena fighting game with customizable sci-fi fighters.', 'Defeat a gauntlet of futuristic opponents to become the champion.', 'A Japan-exclusive fighting game known for its fast-paced action.', 'Space Dynamites (Japan) offers unique character designs and a technical combat system. Master the various fighting styles in this rare and visually distinct N64 brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-invaders-usa', 'N64', 'Space Invaders (USA)', '1999', 'Shooter', 'Video System', '2', 'Classic Shooter', 'Fixed-shooter arcade gameplay with updated 3D graphics.', 'Defeat the invading alien waves before they reach the ground.', 'A modern reimagining of the classic arcade shooter.', 'Space Invaders (USA) brings the legendary franchise to the 64-bit era. Experience new weapon types, massive bosses, and cinematic effects while staying true to the addictive core gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spacestation-silicon-valley-europe-enfrdeesitnlpt', 'N64', 'SpaceStation Silicon Valley (Europe) (En,Fr,De,Es,It,Nl,Pt)', '1998', 'Platform', 'Traveller’s Tales', '1', 'Action Platformer', 'Third-person puzzle-platformer featuring animal possession.', 'Control various animals to solve puzzles and fix the space station.', 'A highly innovative and quirky adventure game from DMA Design.', 'SpaceStation Silicon Valley (Europe) is a cult classic. Play as a robotic chip that can possess the bodies of diverse mechanical animals, each with unique abilities required to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spacestation-silicon-valley-japan-proto', 'N64', 'SpaceStation Silicon Valley (Japan) (Proto)', '1998', 'Platform', 'Traveller’s Tales', '1', 'Prototype', 'Third-person puzzle-platformer featuring animal possession.', 'Restore order to the station in this early development build.', 'A rare Japanese prototype of the unique possession-based game.', 'SpaceStation Silicon Valley (Japan) (Proto) offers a glimpse into the development of this creative title. Experience the core "body-hopping" mechanic in this unreleased regional version for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spacestation-silicon-valley-usa', 'N64', 'SpaceStation Silicon Valley (USA)', '1998', 'Platform', 'Traveller’s Tales', '1', 'Action Platformer', 'Third-person puzzle-platformer featuring animal possession.', 'Stop the evil intentions of the station''s computer system.', 'The North American release of the innovative animal-puzzle game.', 'SpaceStation Silicon Valley (USA) is celebrated for its creativity. Master over 40 different animal forms, from flying sheep to rolling turtles, to solve environmental puzzles in a massive space habitat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speed-star-adventure', 'N64', 'Speed Star Adventure', '2023', 'Platform', 'Independent', '1', 'Indie Platformer', '3D platforming with a focus on speed and star-themed levels.', 'Navigate a series of challenging cosmic environments.', 'A vibrant custom level hack for the Super Mario 64 engine.', 'Speed Star Adventure is all about momentum. Explore custom worlds with star-inspired aesthetics and technical platforming challenges that test your mastery of the N64''s most iconic engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-usa', 'N64', 'Spider-Man (USA)', '2000', 'Action', 'Neversoft', '1', 'Action Adventure', 'Third-person action-adventure with stealth and web-swinging.', 'Stop the Sinister Six and save New York from a symbiote invasion.', 'A legendary superhero game with deep story and unlockables.', 'Spider-Man (USA) captures the essence of the web-slinger. Swing through the city, use stealth to infiltrate bases, and battle iconic villains in one of the best superhero experiences on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-in-smash-remix-150', 'N64', 'Spider-Man in Smash Remix 1.5.0', '2023', 'Fighting', 'Independent', '4', 'Character Mod', '2.5D crossover fighting with custom character move sets.', 'Win the Smash tournament using Spider-Man''s web-based combat.', 'A character mod for Smash Remix 1.5.0 adding the Marvel hero.', 'Spider-Man in Smash Remix 1.5.0 brings Peter Parker to the Nintendo roster. Use web-shooters and acrobatic agility to dominate opponents in this high-quality community expansion for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('squash-64', 'N64', 'Squash 64', '2023', 'Sports', 'Independent', '2', 'Squash Simulation', 'Professional squash simulation with realistic court physics.', 'Win the tournament by outmaneuvering opponents on the squash court.', 'A sports simulation focused on the competitive game of Squash.', 'Squash 64 provides an authentic representation of the sport. Master timing and positioning to win rallies against challenging AI in this specialized and rare sports title for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-fox-64-japan', 'N64', 'Star Fox 64 (Japan)', '1997', 'Shooter', 'Nintendo', '4', 'Rail Shooter', 'On-rail shooter with branching paths and vehicular variety.', 'Protect the Lylat system and defeat the evil scientist Andross.', 'The original Japanese release of the cinematic flight shooter.', 'Star Fox 64 (Japan) revolutionized the genre with its cinematic presentation and "Rumble Pak" support. Lead Fox McCloud and his team through epic space and planetary battles.');